// Text-shape signals only. Never change options or infer medical correctness.
function optionStyleMetrics(question) {
  const q = question && typeof question === 'object' ? question : {};
  const letters = ['A', 'B', 'C', 'D'];
  const options = Array.isArray(q.options) ? q.options : letters.map(k => q.options && q.options[k]);
  const answer = typeof q.answer === 'number' ? q.answer : letters.indexOf(String(q.answer || '').toUpperCase());
  if (options.length !== 4 || options.some(s => typeof s !== 'string' || !s.trim()) || !Number.isInteger(answer) || answer < 0 || answer > 3) return null;
  // Count Unicode characters except spaces/punctuation/symbols; letters/digits count individually.
  const lengths = options.map(s => Array.from(s.replace(/[\s\p{P}\p{S}]/gu, '')).length);
  const wrongLengths = lengths.filter((_, i) => i !== answer).sort((a, b) => a - b);
  const medianWrong = wrongLengths[1];
  const longest = Math.max(...lengths), shortest = Math.min(...lengths);
  const uniqueLongest = lengths[answer] === longest && lengths.filter(n => n === longest).length === 1;
  const codes = [];
  if (uniqueLongest && lengths[answer] - medianWrong >= 6 && lengths[answer] > medianWrong * 1.4) codes.push('CORRECT_OPTION_LONGER');
  if (longest - shortest >= 8 && longest > shortest * 1.5) codes.push('OPTION_LENGTH_SPREAD');
  // These phrases are review clues, not proof that the corresponding option is wrong.
  const absolutePattern = /所有.{0,12}(?:均|都)|(?:一定|必然|必为|必定|绝不|完全可靠)|不会(?:发生|复发)|无需(?:任何|所有)|停止所有|放弃所有|等待自然病程/;
  const absolutePositions = options.map((s, i) => absolutePattern.test(s) ? letters[i] : null).filter(Boolean);
  if (absolutePositions.length && !absolutePositions.includes(letters[answer])) codes.push('DISTRACTOR_ABSOLUTE_CUE');
  const warnings = [];
  if (codes.includes('CORRECT_OPTION_LONGER')) warnings.push('正确项独自较长：应复核是否只有正确项包含条件、理由或多个动作。');
  if (codes.includes('OPTION_LENGTH_SPREAD')) warnings.push('四项长度差异较大：应统一表达层次，不得机械补字或截断。');
  if (codes.includes('DISTRACTOR_ABSOLUTE_CUE')) warnings.push('干扰项含绝对化或极端措辞：需复核是否构成无需医学推理的排除线索，不能仅凭关键词判错。');
  return {
    version: 'option-style-1.0', length_unit: 'unicode_chars_excluding_spaces_punctuation_symbols',
    option_lengths: lengths, answer_position: letters[answer], correct_is_unique_longest: uniqueLongest,
    correct_to_distractor_median_ratio: medianWrong ? Number((lengths[answer] / medianWrong).toFixed(2)) : null,
    max_min_difference: longest - shortest,
    max_min_ratio: shortest ? Number((longest / shortest).toFixed(2)) : null,
    absolute_phrase_positions: absolutePositions, warning_codes: codes, warnings,
    interpretation: '仅为措辞线索，不是医学质量评分；无提示也不等于无缺陷。药名、缩写或必要条件可能导致合理长度差异。'
  };
}

function main(inputs) {
  const source = inputs && typeof inputs === "object" ? inputs : {};
  const ROOT_FIELDS = [
    "schema_version",
    "generation_status",
    "case_summary",
    "question_count",
    "difficulty",
    "questions",
    "missing_information",
    "risk_message"
  ];
  const INTERNAL_QUESTION_FIELDS = [
    "id",
    "type",
    "phase",
    "timepoint",
    "question",
    "options",
    "answer",
    "answer_text",
    "explain",
    "keyPoint",
    "evidence_id",
    "support_mode",
    "evidence_summary"
  ];
  const PUBLIC_QUESTION_FIELDS = [
    "id",
    "type",
    "phase",
    "timepoint",
    "question",
    "options",
    "answer",
    "answer_text",
    "explain",
    "keyPoint"
  ];
  const REF_FIELDS = [
    "evidence_type",
    "doc_id",
    "split_index",
    "type",
    "authority",
    "source_title",
    "source_version",
    "source_section",
    "source_url",
    "evidence_summary"
  ];
  const ABILITY_TYPES = new Set([
    "诊断与分期",
    "分子诊断",
    "治疗决策",
    "疗效复评与局部治疗",
    "耐药与后线管理",
    "不良反应管理"
  ]);
  const SUPPORT_MODES = new Set(["hard", "clinical_reasoning"]);
  const FORBIDDEN_MODEL_METADATA = [
    "guidelineRef",
    "evidence_type",
    "doc_id",
    "split_index",
    "authority",
    "source_title",
    "source_version",
    "source_section",
    "source_url"
  ];
  const FULL_INTERNAL_FIELDS = INTERNAL_QUESTION_FIELDS.filter(
    (field) => field !== "id"
  );
  const errors = [];
  const warnings = [];
  const repairTasks = [];
  const repairTaskKeys = new Set();
  let requiresFullRevision = false;

  function hasOwn(object, key) {
    return Boolean(object && Object.prototype.hasOwnProperty.call(object, key));
  }

  function nonEmptyString(value) {
    return typeof value === "string" && Boolean(value.trim());
  }

  function normalizedText(value) {
    return typeof value === "string" ? value.replace(/\s+/g, " ").trim() : "";
  }

  function pushTask(task) {
    if (task.scope === "root" || task.scope === "set") {
      requiresFullRevision = true;
    }
    const normalized = {
      target_ids: Array.from(
        new Set(
          (Array.isArray(task.target_ids) ? task.target_ids : []).filter(
            (id) => typeof id === "string" && /^Q[1-5]$/.test(id)
          )
        )
      ),
      code: nonEmptyString(task.code) ? task.code : "STRUCTURE_ERROR",
      fields: Array.from(
        new Set(
          (Array.isArray(task.fields) ? task.fields : []).filter(
            (field) => typeof field === "string" && field
          )
        )
      ),
      message: nonEmptyString(task.message) ? task.message : "修复机械结构错误"
    };
    const key = JSON.stringify(normalized);
    if (repairTaskKeys.has(key)) return;
    repairTaskKeys.add(key);
    repairTasks.push(normalized);
  }

  function fail(message, task) {
    errors.push(message);
    if (task) pushTask(task);
  }

  function questionTask(id, code, fields, message) {
    return {
      scope: "question",
      target_ids: /^Q[1-5]$/.test(String(id)) ? [String(id)] : [],
      code,
      fields,
      message
    };
  }

  function setTask(code, targetIds, message) {
    return {
      scope: "set",
      target_ids: targetIds,
      code,
      fields: FULL_INTERNAL_FIELDS,
      message
    };
  }

  function rootTask(code, fields, message) {
    return {
      scope: "root",
      target_ids: [],
      code,
      fields,
      message
    };
  }

  function readJsonStringEnd(text, start) {
    let escaped = false;
    for (let index = start + 1; index < text.length; index++) {
      const char = text[index];
      if (escaped) escaped = false;
      else if (char === "\\") escaped = true;
      else if (char === '"') return index + 1;
    }
    return -1;
  }

  function skipJsonWhitespace(text, start) {
    let cursor = start;
    while (cursor < text.length && /\s/.test(text[cursor])) cursor += 1;
    return cursor;
  }

  function scanJsonValueEnd(text, start) {
    const first = text[start];
    if (first === '"') return readJsonStringEnd(text, start);
    if (first !== "{" && first !== "[") {
      let cursor = start;
      while (
        cursor < text.length &&
        text[cursor] !== "," &&
        text[cursor] !== "}" &&
        text[cursor] !== "]"
      ) {
        cursor += 1;
      }
      return cursor;
    }

    let objectDepth = 0;
    let arrayDepth = 0;
    let inString = false;
    let escaped = false;
    for (let index = start; index < text.length; index++) {
      const char = text[index];
      if (inString) {
        if (escaped) escaped = false;
        else if (char === "\\") escaped = true;
        else if (char === '"') inString = false;
        continue;
      }
      if (char === '"') {
        inString = true;
        continue;
      }
      if (char === "{") objectDepth += 1;
      else if (char === "}") objectDepth -= 1;
      else if (char === "[") arrayDepth += 1;
      else if (char === "]") arrayDepth -= 1;
      if (objectDepth === 0 && arrayDepth === 0) return index + 1;
    }
    return -1;
  }

  function duplicateRootKeys(text) {
    let cursor = skipJsonWhitespace(text, 0);
    if (text[cursor] !== "{") return [];
    cursor += 1;
    const seen = new Set();
    const duplicates = new Set();

    while (cursor < text.length) {
      cursor = skipJsonWhitespace(text, cursor);
      if (text[cursor] === "}") break;
      if (text[cursor] !== '"') return [];
      const keyEnd = readJsonStringEnd(text, cursor);
      if (keyEnd < 0) return [];
      let key;
      try {
        key = JSON.parse(text.slice(cursor, keyEnd));
      } catch (_) {
        return [];
      }
      if (seen.has(key)) duplicates.add(key);
      seen.add(key);
      cursor = skipJsonWhitespace(text, keyEnd);
      if (text[cursor] !== ":") return [];
      cursor = skipJsonWhitespace(text, cursor + 1);
      const valueEnd = scanJsonValueEnd(text, cursor);
      if (valueEnd <= cursor) return [];
      cursor = skipJsonWhitespace(text, valueEnd);
      if (text[cursor] === ",") {
        cursor += 1;
        continue;
      }
      if (text[cursor] === "}") break;
      return [];
    }
    return Array.from(duplicates).sort();
  }

  function parseCandidate(value) {
    if (value && typeof value === "object" && !Array.isArray(value)) {
      return { parsed: value, raw: JSON.stringify(value), error: "" };
    }
    if (typeof value !== "string" || !value.trim()) {
      return { parsed: null, raw: "", error: "候选为空或不是JSON对象/字符串" };
    }
    try {
      const parsed = JSON.parse(value);
      if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
        return {
          parsed: null,
          raw: value,
          error: "候选根值必须是JSON对象"
        };
      }
      const duplicates = duplicateRootKeys(value);
      if (duplicates.length > 0) {
        return {
          parsed: null,
          raw: value,
          error: `候选根对象存在重复键：${duplicates.join("、")}`
        };
      }
      return { parsed, raw: value, error: "" };
    } catch (error) {
      return {
        parsed: null,
        raw: value,
        error: `候选不能被JSON.parse直接解析：${String(
          error && error.message ? error.message : error
        )}`
      };
    }
  }

  function parsePool(value) {
    if (typeof value === "string") {
      if (!value.trim()) return { pool: {}, error: "evidence_pool为空" };
      try {
        const parsed = JSON.parse(value);
        return {
          pool: parsed && typeof parsed === "object" ? parsed : {},
          error:
            parsed && typeof parsed === "object"
              ? ""
              : "evidence_pool根值不是对象或数组"
        };
      } catch (error) {
        return {
          pool: {},
          error: `evidence_pool不能被JSON.parse直接解析：${String(
            error && error.message ? error.message : error
          )}`
        };
      }
    }
    if (value && typeof value === "object") return { pool: value, error: "" };
    return { pool: {}, error: "evidence_pool为空或不是对象" };
  }

  function poolRecords(pool) {
    if (Array.isArray(pool)) return pool;
    if (Array.isArray(pool.records)) return pool.records;
    const records = [];
    for (const lane of [
      "guideline_a",
      "guideline_b",
      "clinical_study_initial",
      "clinical_study_supplement",
      "irae_a",
      "irae_b"
    ]) {
      if (!Array.isArray(pool[lane])) continue;
      records.push(
        ...pool[lane].filter(
          (record) => record && typeof record === "object" && !Array.isArray(record)
        )
      );
    }
    return records;
  }

  function locatorKey(docId, splitIndex) {
    return `${String(docId)}::${String(splitIndex)}`;
  }

  function recordHardType(record) {
    if (["指南", "临床研究"].includes(record.hard_evidence_type)) {
      return record.hard_evidence_type;
    }
    const type = String(record.type || "").toLowerCase();
    if (type === "guideline" && nonEmptyString(record.authority)) return "指南";
    if (
      (record.lane === "clinical_study_initial" ||
        record.lane === "clinical_study_supplement") &&
      record.eligible_clinical_study === true
    ) {
      return "临床研究";
    }
    return "";
  }

  function recordReasoningEligible(record) {
    return record.reasoning_eligible === true || Boolean(recordHardType(record));
  }

  function forbiddenAnswerLetter(text) {
    const value = String(text === null || text === undefined ? "" : text);
    return (
      /正确答案(?:为|是|：|:)?\s*[ABCD](?![A-Za-z])/i.test(value) ||
      /选项\s*[ABCD](?![A-Za-z])/i.test(value) ||
      /[ABCD]\s*项(?![A-Za-z])/i.test(value)
    );
  }

  function hasAuditableQuestion(questions) {
    if (!Array.isArray(questions)) return false;
    return questions.some((question) => {
      if (!question || typeof question !== "object" || Array.isArray(question)) {
        return false;
      }
      if (nonEmptyString(question.question)) return true;
      if (Array.isArray(question.options) && question.options.some(nonEmptyString)) {
        return true;
      }
      return ["answer_text", "explain", "keyPoint", "timepoint"].some((field) =>
        nonEmptyString(question[field])
      );
    });
  }

  function blankReference(summary) {
    return {
      evidence_type: "",
      doc_id: "",
      split_index: "",
      type: "",
      authority: "",
      source_title: "",
      source_version: "",
      source_section: "",
      source_url: "",
      evidence_summary: typeof summary === "string" ? summary : ""
    };
  }

  function hydrateQuestion(question, record, evidenceType) {
    if (!question || typeof question !== "object" || Array.isArray(question)) {
      return question;
    }
    const hydrated = {};
    for (const field of PUBLIC_QUESTION_FIELDS) {
      if (hasOwn(question, field)) hydrated[field] = question[field];
    }
    const reference = blankReference(question.evidence_summary);
    if (record) {
      reference.evidence_type = evidenceType;
      reference.doc_id = hasOwn(record, "doc_id") ? record.doc_id : "";
      reference.split_index = hasOwn(record, "split_index")
        ? record.split_index
        : "";
      reference.type = typeof record.type === "string" ? record.type : "";
      reference.authority =
        typeof record.authority === "string" ? record.authority : "";
      reference.source_title =
        typeof record.source_title === "string" ? record.source_title : "";
      reference.source_version =
        typeof record.source_version === "string" ? record.source_version : "";
      reference.source_section =
        typeof record.source_section === "string" ? record.source_section : "";
      reference.source_url =
        typeof record.source_url === "string" ? record.source_url : "";
    }
    hydrated.guidelineRef = reference;
    return hydrated;
  }

  function validatorFullPool(pool, records) {
    const lanes =
      pool && pool.lanes && typeof pool.lanes === "object" && !Array.isArray(pool.lanes)
        ? pool.lanes
        : Object.fromEntries(
            [
              "guideline_a",
              "guideline_b",
              "clinical_study_initial",
              "clinical_study_supplement",
              "irae_a",
              "irae_b"
            ].map((lane) => [
              lane,
              records
                .filter((record) => record && record.lane === lane)
                .map((record) => record.evidence_id)
            ])
          );
    return {
      audit_mode: "FULL_POOL_FOR_INSUFFICIENCY",
      contract_version: pool.contract_version || "1.2",
      records,
      lanes,
      capacity_report:
        pool && pool.capacity_report && typeof pool.capacity_report === "object"
          ? pool.capacity_report
          : {},
      retrieval_health:
        pool && pool.retrieval_health && typeof pool.retrieval_health === "object"
          ? pool.retrieval_health
          : { ok: false, errors: [{ lane: "registry", message: "缺少检索健康状态" }] },
      compression_report:
        pool && pool.compression_report && typeof pool.compression_report === "object"
          ? pool.compression_report
          : {}
    };
  }

  function buildReturn({
    decision,
    medicalAuditable,
    publicCandidate,
    internalRaw,
    citedRecords,
    validatorEvidence,
    hardCount,
    reasoningCount
  }) {
    const publicRaw = publicCandidate ? JSON.stringify(publicCandidate) : "";
    const publicReferenceMap =
      publicCandidate && Array.isArray(publicCandidate.questions)
        ? publicCandidate.questions
            .filter((question) => question && typeof question === "object" && !Array.isArray(question))
            .map((question) => ({
              id: typeof question.id === "string" ? question.id : "",
              guidelineRef:
                question.guidelineRef && typeof question.guidelineRef === "object"
                  ? question.guidelineRef
                  : blankReference("")
            }))
        : [];
    const recommendedRevisionMode =
      errors.length === 0
        ? ""
        : requiresFullRevision
          ? "FULL"
          : "PATCH";
    return {
      structure_decision: decision,
      structure_errors: errors,
      structure_warnings: warnings,
      medical_auditable: medicalAuditable,
      candidate_json_passthrough: publicRaw,
      public_reference_map_json: JSON.stringify(publicReferenceMap),
      internal_candidate_json: internalRaw,
      cited_evidence: citedRecords,
      cited_evidence_json: JSON.stringify(citedRecords),
      validator_evidence_json: JSON.stringify(validatorEvidence),
      repair_tasks: repairTasks,
      repair_tasks_json: JSON.stringify(repairTasks),
      recommended_revision_mode: recommendedRevisionMode,
      hard_evidence_count: hardCount,
      clinical_reasoning_count: reasoningCount
    };
  }

  const candidateResult = parseCandidate(source.candidate_json);
  const poolResult = parsePool(source.evidence_pool);
  const records = poolRecords(poolResult.pool).filter(
    (record) => record && typeof record === "object" && !Array.isArray(record)
  );

  if (candidateResult.error) {
    fail(
      candidateResult.error,
      rootTask("JSON_PARSE", ROOT_FIELDS, "输出一个可被JSON.parse直接解析的完整内部候选对象")
    );
    return buildReturn({
      decision: "FAIL",
      medicalAuditable: false,
      publicCandidate: null,
      internalRaw: candidateResult.raw,
      citedRecords: [],
      validatorEvidence: [],
      hardCount: 0,
      reasoningCount: 0
    });
  }

  const candidate = candidateResult.parsed;
  const questions = Array.isArray(candidate.questions) ? candidate.questions : [];
  // Warning-only: the independent reviewer decides whether the wording leaks the answer.
  questions.forEach((q, index) => {
    const style = optionStyleMetrics(q);
    if (style && style.warnings.length) warnings.push(
      'OPTION_STYLE ' + (q.id || 'Q' + (index + 1)) +
      '：四项有效字符数=' + style.option_lengths.join('/') +
      '，正确项=' + style.answer_position + '；' + style.warnings.join(' ')
    );
  });
  const medicalAuditable =
    candidate.generation_status === "insufficient" || hasAuditableQuestion(questions);

  if (poolResult.error) {
    fail(
      poolResult.error,
      rootTask(
        "EVIDENCE_POOL_INVALID",
        ["evidence_pool"],
        "修复证据池输入后重新装配，禁止猜测来源元数据"
      )
    );
  } else {
    const health = poolResult.pool && poolResult.pool.retrieval_health;
    if (!health || typeof health !== "object" || typeof health.ok !== "boolean") {
      fail(
        "证据池缺少可核验的retrieval_health状态",
        rootTask("RETRIEVAL_HEALTH_MISSING", ["evidence_pool"], "修复检索错误接线与证据注册后重新执行")
      );
    } else if (health.ok !== true) {
      const messages = Array.isArray(health.errors)
        ? health.errors
            .map((item) => `${String(item && item.lane ? item.lane : "unknown")}: ${String(item && item.message ? item.message : "检索失败")}`)
            .join("；")
        : "检索节点返回错误";
      fail(
        `证据检索链存在技术错误：${messages}`,
        rootTask("RETRIEVAL_FAILURE", ["evidence_pool"], "修复检索工具错误后重新运行；不得把技术空结果判为医学证据不足")
      );
    }
  }

  for (const field of ROOT_FIELDS) {
    if (!hasOwn(candidate, field)) {
      fail(
        `根对象缺少字段：${field}`,
        rootTask("ROOT_FIELD_MISSING", [field], `补齐根字段${field}`)
      );
    }
  }
  if (candidate.schema_version !== "1.1") {
    fail(
      "schema_version必须逐字等于1.1",
      rootTask("SCHEMA_VERSION", ["schema_version"], "schema_version固定为1.1")
    );
  }
  if (candidate.difficulty !== "进阶") {
    fail(
      "difficulty必须逐字等于进阶",
      rootTask("DIFFICULTY", ["difficulty"], "difficulty固定为进阶")
    );
  }
  if (typeof candidate.case_summary !== "string") {
    fail(
      "case_summary必须为字符串",
      rootTask("CASE_SUMMARY_TYPE", ["case_summary"], "输出脱敏且忠实的病例摘要")
    );
  } else if (!candidate.case_summary.trim()) {
    fail(
      "case_summary必须为非空字符串",
      rootTask("CASE_SUMMARY_EMPTY", ["case_summary"], "输出非空、脱敏且忠实的病例摘要")
    );
  } else if (candidate.case_summary.length > 400) {
    fail(
      "case_summary超过400字",
      rootTask("CASE_SUMMARY_LENGTH", ["case_summary"], "在不改写病例事实的前提下将摘要限制在400字内")
    );
  }

  const publicCandidate = {};
  for (const field of ROOT_FIELDS) {
    if (field !== "questions" && hasOwn(candidate, field)) {
      publicCandidate[field] = candidate[field];
    }
  }

  if (candidate.generation_status === "insufficient") {
    if (candidate.question_count !== 0) {
      fail(
        "insufficient时question_count必须为0",
        rootTask("INSUFFICIENT_COUNT", ["question_count"], "insufficient时题量固定为0")
      );
    }
    if (!Array.isArray(candidate.questions) || candidate.questions.length !== 0) {
      fail(
        "insufficient时questions必须为空数组",
        rootTask("INSUFFICIENT_QUESTIONS", ["questions"], "insufficient时不得夹带候选题")
      );
    }
    if (
      !Array.isArray(candidate.missing_information) ||
      candidate.missing_information.length === 0 ||
      candidate.missing_information.some((item) => !nonEmptyString(item))
    ) {
      fail(
        "insufficient时missing_information必须为具体的非空字符串数组",
        rootTask(
          "INSUFFICIENT_MISSING_INFORMATION",
          ["missing_information"],
          "列明缺少的证据类型、适用人群或独立决策方向"
        )
      );
    }
    if (!nonEmptyString(candidate.risk_message)) {
      fail(
        "insufficient时risk_message必须具体且非空",
        rootTask("INSUFFICIENT_RISK", ["risk_message"], "具体说明为何不能安全形成固定五题")
      );
    }
    publicCandidate.questions = [];
    return buildReturn({
      decision: errors.length === 0 ? "INSUFFICIENT" : "FAIL",
      medicalAuditable,
      publicCandidate,
      internalRaw: candidateResult.raw,
      citedRecords: [],
      validatorEvidence: validatorFullPool(poolResult.pool, records),
      hardCount: 0,
      reasoningCount: 0
    });
  }

  if (candidate.generation_status !== "success") {
    fail(
      "generation_status只能为success或insufficient",
      rootTask(
        "GENERATION_STATUS",
        ["generation_status"],
        "根据实际结果输出success或insufficient"
      )
    );
  }
  if (candidate.question_count !== 5) {
    fail(
      "success时question_count必须为5",
      rootTask("QUESTION_COUNT", ["question_count", "questions"], "success时完整生成Q1至Q5")
    );
  }
  if (!Array.isArray(candidate.questions) || candidate.questions.length !== 5) {
    fail(
      "success时questions必须恰好包含5题",
      rootTask("QUESTION_SET_SIZE", ["questions"], "FULL重建恰好Q1至Q5五题")
    );
  }
  if (
    !Array.isArray(candidate.missing_information) ||
    candidate.missing_information.length !== 0
  ) {
    fail(
      "success时missing_information必须为空数组",
      rootTask("SUCCESS_MISSING_INFORMATION", ["missing_information"], "success时清空missing_information")
    );
  }
  if (candidate.risk_message !== "") {
    fail(
      "success时risk_message必须为空字符串",
      rootTask("SUCCESS_RISK_MESSAGE", ["risk_message"], "success时risk_message必须为空字符串")
    );
  }

  const evidenceById = new Map();
  const evidenceByLocator = new Map();
  for (const record of records) {
    const evidenceId = record.evidence_id;
    if (nonEmptyString(evidenceId)) {
      const list = evidenceById.get(evidenceId) || [];
      list.push(record);
      evidenceById.set(evidenceId, list);
    }
    if (hasOwn(record, "doc_id") && hasOwn(record, "split_index")) {
      const locator = locatorKey(record.doc_id, record.split_index);
      const list = evidenceByLocator.get(locator) || [];
      list.push(record);
      evidenceByLocator.set(locator, list);
    }
  }

  const hydratedQuestions = [];
  const citedRecords = [];
  const citedEvidenceIds = new Set();
  const locatorUsage = new Map();
  let hardCount = 0;
  let reasoningCount = 0;

  for (let index = 0; index < questions.length; index++) {
    const question = questions[index];
    const expectedId = `Q${index + 1}`;
    const taskId =
      question && typeof question === "object" && /^Q[1-5]$/.test(String(question.id))
        ? String(question.id)
        : expectedId;

    if (!question || typeof question !== "object" || Array.isArray(question)) {
      fail(
        `第${index + 1}题不是对象`,
        setTask("QUESTION_NOT_OBJECT", [expectedId], `完整重建${expectedId}`)
      );
      hydratedQuestions.push(question);
      continue;
    }

    for (const field of INTERNAL_QUESTION_FIELDS) {
      if (!hasOwn(question, field)) {
        fail(
          `${taskId}缺少字段：${field}`,
          questionTask(taskId, "QUESTION_FIELD_MISSING", [field], `补齐${taskId}.${field}`)
        );
      }
    }
    const forbiddenFields = FORBIDDEN_MODEL_METADATA.filter((field) =>
      hasOwn(question, field)
    );
    if (forbiddenFields.length > 0) {
      fail(
        `${taskId}包含禁止由模型填写的来源元数据：${forbiddenFields.join("、")}`,
        questionTask(
          taskId,
          "MODEL_SUPPLIED_EVIDENCE_METADATA",
          forbiddenFields,
          "删除模型填写的来源元数据，只保留evidence_id、support_mode与evidence_summary"
        )
      );
    }
    if (question.id !== expectedId) {
      fail(
        `第${index + 1}题id必须为${expectedId}`,
        setTask("QUESTION_ID_SEQUENCE", questions.map((item, i) => `Q${i + 1}`), "FULL重建并按Q1至Q5编号")
      );
    }
    if (!ABILITY_TYPES.has(question.type)) {
      fail(
        `${taskId}的type不在六项允许值中`,
        questionTask(taskId, "ABILITY_TYPE", ["type"], "将type改为匹配主要能力的允许值")
      );
    }
    for (const field of [
      "phase",
      "timepoint",
      "question",
      "answer_text",
      "explain",
      "keyPoint",
      "evidence_id",
      "support_mode",
      "evidence_summary"
    ]) {
      if (!nonEmptyString(question[field])) {
        fail(
          `${taskId}的${field}必须为非空字符串`,
          questionTask(taskId, "EMPTY_FIELD", [field], `补齐${taskId}.${field}`)
        );
      }
    }

    if (!Array.isArray(question.options) || question.options.length !== 4) {
      fail(
        `${taskId}的options必须恰好4项`,
        questionTask(taskId, "OPTION_COUNT", ["options", "answer", "answer_text"], "重建4个选项并同步答案")
      );
    } else {
      if (question.options.some((option) => !nonEmptyString(option))) {
        fail(
          `${taskId}存在空选项或非字符串选项`,
          questionTask(taskId, "EMPTY_OPTION", ["options", "answer", "answer_text"], "重建4个非空字符串选项并同步答案")
        );
      }
      const normalizedOptions = question.options.map(normalizedText);
      if (new Set(normalizedOptions).size !== 4) {
        fail(
          `${taskId}存在重复选项`,
          questionTask(taskId, "DUPLICATE_OPTIONS", ["options", "answer", "answer_text"], "重建4个互不重复的选项并同步答案")
        );
      }
      if (
        question.options.some((option) =>
          /以上(?:都|全|均)(?:是|正确)|以上(?:都|均)不是/.test(String(option))
        )
      ) {
        fail(
          `${taskId}包含以上都是/以上都不是类选项`,
          questionTask(taskId, "SHORTCUT_OPTION", ["options", "answer", "answer_text"], "用独立且可判断的临床干扰项替换捷径选项")
        );
      }
      question.options.forEach((option, optionIndex) => {
        if (typeof option === "string" && option.length > 60) {
          fail(
            `${taskId}选项${optionIndex + 1}超过60字`,
            questionTask(taskId, "OPTION_LENGTH", ["options", "answer", "answer_text"], "在不改变医学结论的前提下将每个选项限制在60字内")
          );
        }
      });
    }

    if (!Number.isInteger(question.answer) || question.answer < 0 || question.answer > 3) {
      fail(
        `${taskId}的answer必须为0至3整数`,
        questionTask(taskId, "ANSWER_INDEX", ["options", "answer", "answer_text"], "修复答案索引并同步answer_text")
      );
    } else if (
      !Array.isArray(question.options) ||
      question.answer_text !== question.options[question.answer]
    ) {
      fail(
        `${taskId}的answer_text与options[answer]不逐字一致`,
        questionTask(taskId, "ANSWER_TEXT_MISMATCH", ["options", "answer", "answer_text"], "使answer_text逐字等于options[answer]")
      );
    }

    if (forbiddenAnswerLetter(question.explain) || forbiddenAnswerLetter(question.keyPoint)) {
      fail(
        `${taskId}的解析或keyPoint含答案字母引用`,
        questionTask(taskId, "ANSWER_LETTER_REFERENCE", ["explain", "keyPoint"], "删除对A/B/C/D或选项字母的指代")
      );
    }
    for (const [field, limit] of [
      ["question", 160],
      ["explain", 160],
      ["keyPoint", 70],
      ["evidence_summary", 80]
    ]) {
      if (typeof question[field] === "string" && question[field].length > limit) {
        fail(
          `${taskId}的${field}超过${limit}字`,
          questionTask(taskId, `${field.toUpperCase()}_LENGTH`, [field], `在不改变医学结论的前提下将${field}限制在${limit}字内`)
        );
      }
    }

    if (!SUPPORT_MODES.has(question.support_mode)) {
      fail(
        `${taskId}的support_mode只能为hard或clinical_reasoning`,
        questionTask(taskId, "SUPPORT_MODE", ["support_mode", "evidence_id", "evidence_summary"], "根据实际证据重新选择允许的support_mode")
      );
    }

    const matches = nonEmptyString(question.evidence_id)
      ? evidenceById.get(question.evidence_id) || []
      : [];
    let record = null;
    let evidenceType = "";
    if (matches.length !== 1) {
      fail(
        `${taskId}的evidence_id在证据池中匹配${matches.length}条，必须恰好1条`,
        questionTask(taskId, "EVIDENCE_ID_NOT_UNIQUE", ["evidence_id", "support_mode", "evidence_summary"], "改用证据池中可唯一定位且直接支持答案的evidence_id")
      );
    } else {
      record = matches[0];
      const locator = locatorKey(record.doc_id, record.split_index);
      const locatorMatches = evidenceByLocator.get(locator) || [];
      if (locatorMatches.length !== 1) {
        fail(
          `${taskId}绑定记录的doc_id+split_index在证据池中匹配${locatorMatches.length}条`,
          rootTask("EVIDENCE_LOCATOR_NOT_UNIQUE", ["evidence_pool"], "修复证据注册去重后重新装配")
        );
      }
      if (question.support_mode === "clinical_reasoning") {
        evidenceType = "病例+临床推理";
        if (!recordReasoningEligible(record)) {
          fail(
            `${taskId}声明clinical_reasoning，但绑定记录未被证据注册节点确认为可引用来源`,
            questionTask(taskId, "REASONING_EVIDENCE_INELIGIBLE", FULL_INTERNAL_FIELDS, "用合格指南、原始研究或身份可机械确认的高质量二级资料完整重建该题")
          );
        } else {
          reasoningCount += 1;
        }
      } else if (question.support_mode === "hard") {
        evidenceType = recordHardType(record);
        if (!evidenceType) {
          fail(
            `${taskId}声明hard，但绑定记录未被证据注册节点确定为合格指南或临床研究`,
            questionTask(taskId, "HARD_EVIDENCE_INELIGIBLE", FULL_INTERNAL_FIELDS, "用合格硬证据完整重建该题，或在非高风险结论下改为真实的临床推理题")
          );
        } else {
          hardCount += 1;
        }
      }
      if (!nonEmptyString(record.source_title)) {
        fail(
          `${taskId}绑定记录缺少source_title`,
          rootTask("SOURCE_TITLE_MISSING", ["evidence_pool"], "修复证据注册的正式来源名称后重新装配")
        );
      }
      if (!nonEmptyString(record.doc_id)) {
        fail(
          `${taskId}绑定记录缺少doc_id`,
          rootTask("DOC_ID_MISSING", ["evidence_pool"], "修复证据注册定位后重新装配")
        );
      }
      if (!hasOwn(record, "split_index") || record.split_index === "") {
        fail(
          `${taskId}绑定记录缺少split_index`,
          rootTask("SPLIT_INDEX_MISSING", ["evidence_pool"], "修复证据注册定位后重新装配")
        );
      }

      const uses = locatorUsage.get(locator) || [];
      uses.push({
        id: taskId,
        timepoint: question.timepoint,
        answer_text: question.answer_text,
        keyPoint: question.keyPoint
      });
      locatorUsage.set(locator, uses);
      if (!citedEvidenceIds.has(record.evidence_id)) {
        citedEvidenceIds.add(record.evidence_id);
        citedRecords.push(record);
      }
    }

    hydratedQuestions.push(hydrateQuestion(question, record, evidenceType));
  }

  for (const [locator, uses] of locatorUsage.entries()) {
    const targetIds = uses.map((use) => use.id).filter((id) => /^Q[1-5]$/.test(id));
    if (uses.length > 2) {
      fail(
        `证据定位${locator}被使用${uses.length}次，超过最多2题`,
        setTask("EVIDENCE_REUSED_OVER_LIMIT", targetIds, "重建受影响题，使同一证据定位最多支持2题")
      );
    }
    if (uses.length === 2) {
      for (const field of ["timepoint", "answer_text", "keyPoint"]) {
        const first = uses[0][field];
        const second = uses[1][field];
        if (!nonEmptyString(first) || !nonEmptyString(second)) {
          fail(
            `证据定位${locator}二次使用时两题的${field}必须均非空`,
            setTask("EVIDENCE_REUSE_EMPTY_FIELD", targetIds, `重建受影响题并补齐不同的${field}`)
          );
        } else if (normalizedText(first) === normalizedText(second)) {
          fail(
            `证据定位${locator}二次使用时两题的${field}必须不同`,
            setTask("EVIDENCE_REUSE_NOT_DISTINCT", targetIds, `重建受影响题，使两题的${field}实质不同`)
          );
        }
      }
    }
  }

  const allExpectedIds = ["Q1", "Q2", "Q3", "Q4", "Q5"];
  if (hardCount < 2) {
    fail(
      "五题中经证据记录确认的hard题少于2道",
      setTask("HARD_QUOTA", allExpectedIds, "FULL重建题集，使合格hard题不少于2道")
    );
  }
  if (reasoningCount < 2) {
    fail(
      "五题中可定位的clinical_reasoning题少于2道",
      setTask("CLINICAL_REASONING_QUOTA", allExpectedIds, "FULL重建题集，使clinical_reasoning题不少于2道")
    );
  }

  publicCandidate.questions = hydratedQuestions;
  for (const question of hydratedQuestions) {
    if (!question || typeof question !== "object" || Array.isArray(question)) continue;
    const ref = question.guidelineRef;
    if (!ref || typeof ref !== "object" || Array.isArray(ref)) {
      fail(
        `${question.id || "题目"}装配后的guidelineRef无效`,
        rootTask("HYDRATION_FAILED", ["guidelineRef"], "修复装配节点后重新执行")
      );
      continue;
    }
    for (const field of REF_FIELDS) {
      if (!hasOwn(ref, field)) {
        fail(
          `${question.id || "题目"}装配后的guidelineRef缺少${field}`,
          rootTask("HYDRATED_REF_FIELD_MISSING", [field], "修复确定性证据装配")
        );
      }
    }
  }

  return buildReturn({
    decision: errors.length === 0 ? "PASS" : "FAIL",
    medicalAuditable,
    publicCandidate,
    internalRaw: candidateResult.raw,
    citedRecords,
    validatorEvidence: citedRecords,
    hardCount,
    reasoningCount
  });
}

outputs.valueDesc:
{
  id: string;
  datasetId: string;
  collectionId: string;
  sourceName: string;
  sourceId?: string;
  q: string;
  a: string
}[]

inputs.value:
function main({ quotes, original_query, initial_studies, guideline_a, guideline_b }) {
  function clean(value) {
    return String(value == null ? "" : value)
      .replace(/<[^>]*>/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  function toRows(value) {
    if (Array.isArray(value)) return value;

    if (typeof value === "string") {
      try {
        const parsed = JSON.parse(value);
        return Array.isArray(parsed) ? parsed : [];
      } catch (_) {
        return value.trim() ? [{ a: value }] : [];
      }
    }

    if (value && Array.isArray(value.quoteQA)) {
      return value.quoteQA;
    }

    return [];
  }

  function unique(values) {
    return Array.from(new Set(values.filter(Boolean)));
  }

  function publicUrl(value) {
    const url = clean(value).replace(/[),.;。，；）]+$/g, "");

    if (!/^https?:\/\//i.test(url)) return "";
    if (/^https?:\/\/(?:localhost|127\.|10\.|192\.168\.|169\.254\.|172\.(?:1[6-9]|2\d|3[01])\.)/i.test(url)) {
      return "";
    }
    if (/[?&](?:token|access_token|api_key|apikey|auth|authorization|credential|signature|sig)=/i.test(url)) {
      return "";
    }

    return url;
  }

  const excluded = new Set([
    "ALK", "NSCLC", "SCLC", "EGFR", "ROS1", "RET", "KRAS", "BRAF",
    "NTRK", "MET", "HER2", "PDL1", "TKI", "DFS", "PFS", "EFS", "OS",
    "ORR", "DCR", "HR", "CI", "CNS", "MPR", "PCR", "NGS", "FISH",
    "ASCO", "ESMO", "WCLC", "AATS", "AACR", "NEJM", "CTRC", "FDA",
    "CTDNA", "MRD"
  ]);

  const rows = toRows(quotes);
  const allStudyNames = [];
  const allRegistryIds = [];
  const studyLeads = [];
  const relatedReading = [];
  const seenReading = new Set();

  for (const item of rows) {
    const title = clean(
      item && (item.title || item.sourceTitle || item.sourceName)
    );
    // FastGPT datasetQuote在不同版本中可能把正文放在q或a；sourceName通常只是文件名。
    // 同时纳入所有正文候选，不能因sourceName存在就忽略q中的研究名称/注册号。
    const body = [
      item && item.q,
      item && item.a,
      item && item.content,
      item && item.text,
      item && item.pageContent
    ].map(clean).filter(Boolean).join(" ");
    const combined = `${title} ${body}`;
    // 标题已经明确给出研究名时只信标题，避免把正文中的国家名、对照研究或延伸讨论误作当前研究。
    // 标题没有研究身份时，有限扫描正文开头，以识别“综述/访谈标题 + 开头明确介绍主研究”的资料。
    const rawQ = String((item && item.q) || "");
    const embeddedTitleMatch = rawQ.match(/标题:\[([^\]]{1,300})\]/);
    const embeddedTitle = clean(embeddedTitleMatch ? embeddedTitleMatch[1] : "");
    const titleHasStudyIdentity = /\b[A-Z][A-Z0-9-]{2,24}(?:\s+\d{2,5})?\s*(?=研究|试验|(?:中国)?数据|study\b|trial\b)/i.test(embeddedTitle);
    const primaryIdentityText = titleHasStudyIdentity
      ? embeddedTitle
      : `${embeddedTitle || title} ${body.slice(0, 1000)}`;

    const registryIds = unique([
      ...((combined.match(/\bNCT\d{8}\b/gi) || []).map((value) => value.toUpperCase())),
      ...((combined.match(/\b\d{4}-\d{6}-\d{2}\b/g) || []))
    ]);

    const studyNames = [];
    const studyPattern = /\b([A-Z][A-Z0-9-]{2,24}(?:\s+\d{2,5})?)\s*(?=研究|试验|(?:中国)?数据|study\b|trial\b)/gi;
    let match;

    while ((match = studyPattern.exec(primaryIdentityText)) !== null) {
      const name = String(match[1] || "").replace(/\s+/g, " ").trim().toUpperCase();
      if (!excluded.has(name) && !/^\d+$/.test(name)) {
        studyNames.push(name);
      }
    }

    // 兼容“Ⅱ期研究（LORIN）”这类研究简称置于括号内的标题写法。
    const parentheticalStudyPattern = /(?:研究|试验)\s*[（(]\s*([A-Z][A-Z0-9-]{2,24}(?:\s+\d{2,5})?)\s*[）)]/gi;
    while ((match = parentheticalStudyPattern.exec(primaryIdentityText)) !== null) {
      const name = String(match[1] || "").replace(/\s+/g, " ").trim().toUpperCase();
      if (!excluded.has(name) && !/^\d+$/.test(name)) {
        studyNames.push(name);
      }
    }

    const normalizedNames = unique(studyNames).slice(0, 5);
    const normalizedRegistryIds = registryIds.slice(0, 5);

    allStudyNames.push(...normalizedNames);
    allRegistryIds.push(...normalizedRegistryIds);

    const directUrl = publicUrl(
      item && (item.sourceUrl || item.url || item.link || item.sourceLink)
    );
    const textUrlMatch = combined.match(/https?:\/\/[^\s<>"']+/i);
    const leadUrl = directUrl || publicUrl(textUrlMatch ? textUrlMatch[0] : "");
    const sourceRecordId = clean(item && (item.id || item.sourceId));

    if (normalizedNames.length > 0 || normalizedRegistryIds.length > 0) {
      studyLeads.push({
        study_names: normalizedNames,
        registry_ids: normalizedRegistryIds,
        article_title: title,
        lead_url: leadUrl,
        source_record_id: sourceRecordId,
        source_kind: "资讯线索，不作主证据"
      });
    }

    const readingKey = `${title}|${leadUrl}|${sourceRecordId}`;
    if (title && !seenReading.has(readingKey)) {
      seenReading.add(readingKey);
      relatedReading.push({
        title,
        url: leadUrl,
        source_record_id: sourceRecordId,
        source_type: "资讯解读"
      });
    }
  }

  const studyNames = unique(allStudyNames).slice(0, 8);
  const registryIds = unique(allRegistryIds).slice(0, 8);
  const expandedTerms = [...studyNames, ...registryIds].join(" ");
  function rowsFromResult(value) {
    if (Array.isArray(value)) return value;
    if (value && Array.isArray(value.result)) return value.result;
    if (typeof value === "string") {
      try {
        const parsed = JSON.parse(value);
        return Array.isArray(parsed) ? parsed : (Array.isArray(parsed?.result) ? parsed.result : []);
      } catch (_) { return []; }
    }
    return [];
  }

  function recordText(item) {
    try { return clean(JSON.stringify(item)); } catch (_) { return clean(item); }
  }

  function clearlyEligibleStudy(item) {
    const value = recordText(item);
    const identity = /(?:\bNCT\d{8}\b|\b[A-Z][A-Z0-9-]{2,24}\s*(?:研究|试验|study|trial)|临床试验)/i.test(value);
    const design = /(?:随机|开放标签|单臂|双盲|前瞻性|回顾性|phase\s*[1-4]|[ⅠⅡⅢⅣIVX]+期)/i.test(value);
    const population = /(?:入组|纳入|患者|patients?|受试者)/i.test(value);
    const intervention = /(?:治疗|方案|联合|单药|versus|\bvs\b|接受)/i.test(value);
    const result = /(?:主要终点|终点|PFS|OS|ORR|DFS|EFS|HR|缓解率|生存期|个月|结果)/i.test(value);
    return identity && design && population && intervention && result;
  }

  function eligibleGuidelineCount(value) {
    const seen = new Set();
    for (const item of rowsFromResult(value)) {
      if (String(item?.type || "") !== "guideline" || !clean(item?.authority)) continue;
      const doc = clean(item?.docId ?? item?.doc_id);
      const split = item?.splitIndex ?? item?.split_index;
      if (doc && split !== undefined && split !== null && split !== "") seen.add(`${doc}::${String(split)}`);
    }
    return seen.size;
  }

  const initialStudyRows = rowsFromResult(initial_studies);
  const initialHasEligibleStudy = initialStudyRows.some(clearlyEligibleStudy);
  const baseEligiblePool = eligibleGuidelineCount(guideline_a) + eligibleGuidelineCount(guideline_b) + (initialHasEligibleStudy ? 1 : 0);
  const hasCandidateLeads = expandedTerms.length > 0;
  const hasLeads = hasCandidateLeads;
  const baseQuery = clean(original_query);

  const expandedQuery = hasLeads
    ? `${baseQuery}\n\n【补充知识库抽取的研究线索】\n${expandedTerms}\n\n上述线索仅用于在正式医学数据库中补充检索。只返回当前记录本身能确认研究身份、设计、人群、方案、终点及结果的原始临床研究或正式研究摘要。不得把资讯、解读、专家访谈或会议新闻作为原始研究。`
    : "";

  return {
    has_leads: hasLeads,
    expanded_terms: expandedTerms,
    expanded_query: expandedQuery,
    study_leads_json: JSON.stringify(studyLeads.slice(0, 8)),
    related_reading_json: JSON.stringify(relatedReading.slice(0, 8))
  };
}

function main(inputs) {
  const source = inputs && typeof inputs === "object" ? inputs : {};
  const LANE_DEFINITIONS = [
    { key: "guideline_a", prefix: "GA", limit: 6 },
    { key: "guideline_b", prefix: "GB", limit: 6 },
    { key: "clinical_study_initial", prefix: "CS", limit: 5 },
    { key: "clinical_study_supplement", prefix: "CS", limit: 3 },
    { key: "irae_a", prefix: "IR", limit: 4 },
    { key: "irae_b", prefix: "IR", limit: 4 }
  ];
  const LANE_LIMITS = Object.fromEntries(
    LANE_DEFINITIONS.map((item) => [item.key, item.limit])
  );
  const RETRIEVAL_ERROR_FIELDS = [
    { key: "guideline_a_error", lane: "guideline_a" },
    { key: "guideline_a_system_error", lane: "guideline_a" },
    { key: "guideline_b_error", lane: "guideline_b" },
    { key: "guideline_b_system_error", lane: "guideline_b" },
    { key: "clinical_study_initial_error", lane: "clinical_study_initial" },
    { key: "clinical_study_initial_system_error", lane: "clinical_study_initial" },
    { key: "clinical_study_supplement_error", lane: "clinical_study_supplement" },
    { key: "clinical_study_supplement_system_error", lane: "clinical_study_supplement" },
    { key: "irae_a_error", lane: "irae_a" },
    { key: "irae_a_system_error", lane: "irae_a" },
    { key: "irae_b_error", lane: "irae_b" },
    { key: "irae_b_system_error", lane: "irae_b" },
    { key: "knowledge_search_error", lane: "knowledge_search" }
  ];
  const CONTENT_KEYS = new Set([
    "snippet",
    "text",
    "content",
    "pagecontent",
    "chunk",
    "q",
    "a",
    "answer"
  ]);

  function hasOwn(object, key) {
    return Boolean(object && Object.prototype.hasOwnProperty.call(object, key));
  }

  function parseMaybe(value) {
    if (typeof value !== "string") return value;
    const text = value.trim();
    if (!text) return [];
    try {
      return JSON.parse(text);
    } catch (_) {
      return value;
    }
  }

  function asObject(value) {
    const parsed = parseMaybe(value);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed)
      ? parsed
      : {};
  }

  function hasRecordShape(value) {
    if (!value || typeof value !== "object" || Array.isArray(value)) return false;
    return Object.keys(value).some((key) =>
      /^(doc_?id|docId|documentId|dataId|split_?index|splitIndex|chunkIndex|snippet|text|content|pageContent)$/i.test(
        key
      )
    );
  }

  function toRecords(input) {
    const value = parseMaybe(input);
    if (Array.isArray(value)) {
      return value.flatMap((item) => toRecords(item));
    }
    if (!value || typeof value !== "object") return [];
    if (hasRecordShape(value)) return [value];
    for (const key of [
      "records",
      "results",
      "result",
      "list",
      "data",
      "searchResults",
      "searchResult",
      "chunks"
    ]) {
      if (!hasOwn(value, key)) continue;
      const records = toRecords(value[key]);
      if (records.length > 0) return records;
    }
    return [];
  }

  function metadataOf(record) {
    return asObject(record && (record.metadata || record.metaData || record.meta));
  }

  function pick(record, metadata, keys) {
    for (const key of keys) {
      if (hasOwn(record, key) && record[key] !== null && record[key] !== undefined) {
        return record[key];
      }
      if (
        hasOwn(metadata, key) &&
        metadata[key] !== null &&
        metadata[key] !== undefined
      ) {
        return metadata[key];
      }
    }
    return "";
  }

  function pickNonBlank(record, metadata, keys) {
    for (const key of keys) {
      for (const container of [record, metadata]) {
        if (!hasOwn(container, key)) continue;
        const value = container[key];
        if (value === null || value === undefined) continue;
        if (typeof value === "string" && !value.trim()) continue;
        return value;
      }
    }
    return "";
  }

  function scalarString(value) {
    if (value === null || value === undefined) return "";
    if (typeof value === "string") return value;
    if (typeof value === "number" || typeof value === "boolean") {
      return String(value);
    }
    return "";
  }

  function normalizeSpaces(value) {
    return scalarString(value)
      .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, " ")
      .replace(/\uFFFD/g, "")
      .replace(/\s+/g, " ")
      .trim();
  }

  function decodeHtml(text) {
    const named = {
      amp: "&",
      lt: "<",
      gt: ">",
      quot: '"',
      apos: "'",
      nbsp: " "
    };
    return text
      .replace(/&([a-z]+);/gi, (match, name) =>
        hasOwn(named, name.toLowerCase()) ? named[name.toLowerCase()] : match
      )
      .replace(/&#(\d+);/g, (_, code) => {
        const value = Number(code);
        return Number.isFinite(value) ? String.fromCodePoint(value) : "";
      })
      .replace(/&#x([0-9a-f]+);/gi, (_, code) => {
        const value = parseInt(code, 16);
        return Number.isFinite(value) ? String.fromCodePoint(value) : "";
      });
  }

  function cleanFullText(value) {
    let text = scalarString(value);
    text = text
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ")
      .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ")
      .replace(/<(?:br|\/p|\/li|\/div|\/h[1-6])\s*\/?>/gi, "\n")
      .replace(/<[^>]+>/g, " ");
    text = decodeHtml(text)
      .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, " ")
      .replace(/\uFFFD/g, "")
      .replace(/[\t\f\v]+/g, " ")
      .replace(/ *\n+ */g, "\n")
      .replace(/ {2,}/g, " ")
      .trim();

    const segments = text.match(/[^。！？!?；;\n]+[。！？!?；;]?/g) || [];
    const seen = new Set();
    const unique = [];
    for (const raw of segments) {
      const segment = raw.replace(/\s+/g, " ").trim();
      const key = segment.replace(/[\s。！？!?；;，,、]/g, "").toLowerCase();
      if (!segment || !key || seen.has(key)) continue;
      seen.add(key);
      unique.push(segment);
    }
    // 保留段落边界，避免“Results/结果”标题与下一句黏连后无法识别。
    return unique.join("\n").trim();
  }

  function compressSnippet(fullText, lane) {
    const text = scalarString(fullText).trim();
    if (text.length <= 1000) return text;
    if (lane !== "clinical_study_initial" && lane !== "clinical_study_supplement") {
      return text.slice(0, 1000).trim();
    }

    // 临床研究长摘要的结果段常位于Methods之后。身份判定使用未截断全文；
    // 模型可见snippet则保留题名前文、Results/结果及Conclusion/结论附近文本。
    const windows = [];
    const addWindow = (start, length) => {
      const safeStart = Math.max(0, Math.min(text.length, start));
      const value = text.slice(safeStart, safeStart + length).trim();
      if (value && !windows.includes(value)) windows.push(value);
    };
    addWindow(0, 300);
    const resultsMatch = /(?:^|[\s.;。；])(?:results?|结果)\s*[:：]?/i.exec(text);
    if (resultsMatch) addWindow(Math.max(0, resultsMatch.index - 80), 560);
    const conclusionMatch = /(?:^|[\s.;。；])(?:conclusions?|结论)\s*[:：]?/i.exec(text);
    if (conclusionMatch) addWindow(Math.max(0, conclusionMatch.index - 40), 260);
    if (windows.length === 1) addWindow(Math.max(0, text.length - 650), 650);
    return windows.join("…").slice(0, 1000).trim();
  }

  function sourceText(record, metadata) {
    const direct = pickNonBlank(record, metadata, [
      "snippet",
      "text",
      "content",
      "pageContent",
      "chunk"
    ]);
    if (scalarString(direct).trim()) return direct;
    const q = scalarString(
      pickNonBlank(record, metadata, ["q", "question"])
    ).trim();
    const a = scalarString(
      pickNonBlank(record, metadata, ["a", "answer"])
    ).trim();
    return [q, a].filter(Boolean).join("\n");
  }

  function safeSourceUrl(value) {
    const text = normalizeSpaces(value);
    return /^https?:\/\/\S+$/i.test(text) ? text : "";
  }

  function locatorKey(docId, splitIndex) {
    return `${String(docId)}::${String(splitIndex)}`;
  }

  function validSplitIndex(value) {
    // 发布合同要求非负整数；不把字符串静默改型，以免改变来源定位。
    return Number.isInteger(value) && value >= 0;
  }

  function normalizeRecord(rawRecord, lane) {
    const record = rawRecord && typeof rawRecord === "object" ? rawRecord : {};
    const metadata = metadataOf(record);
    const isClinicalStudyLane =
      lane === "clinical_study_initial" || lane === "clinical_study_supplement";
    const docId = pickNonBlank(record, metadata, [
      "doc_id",
      "docId",
      "document_id",
      "documentId",
      "dataId",
      "sourceId"
    ]);
    const splitIndex = pickNonBlank(record, metadata, [
      "split_index",
      "splitIndex",
      "chunk_index",
      "chunkIndex",
      "index"
    ]);
    const recordTitle = normalizeSpaces(record.title);
    const metadataTitle = normalizeSpaces(metadata.title);
    const studyName = normalizeSpaces(
      pickNonBlank(record, metadata, ["study_name", "studyName"])
    );
    const guidelineName = normalizeSpaces(
      pickNonBlank(record, metadata, ["guideline_name", "guidelineName"])
    );
    const dataSourceName = normalizeSpaces(
      pickNonBlank(record, metadata, ["dataSourceName", "data_source_name"])
    );
    const namedSource = normalizeSpaces(
      pickNonBlank(record, metadata, [
        "formal_title",
        "formalTitle",
        "source_title",
        "sourceName",
        "documentTitle",
        "publicationTitle"
      ])
    );
    const explicitSection = normalizeSpaces(
      pickNonBlank(record, metadata, [
        "source_section",
        "section",
        "heading",
        "chapter",
        "chunk_title",
        "chunkTitle"
      ])
    );
    // 临床研究的dataSourceName常是期刊名；正式研究/文章题名优先来自
    // study_name、metaData.title或record.title。record.title同时保留为分块章节。
    const sourceTitle = isClinicalStudyLane
      ? studyName || metadataTitle || recordTitle || namedSource || dataSourceName
      : dataSourceName || guidelineName || namedSource;
    const sourceSection = isClinicalStudyLane
      ? explicitSection || recordTitle
      : explicitSection || recordTitle || metadataTitle;
    const explicitAuthority = normalizeSpaces(
      pickNonBlank(record, metadata, [
        "authority",
        "issuing_authority",
        "organization"
      ])
    );
    const sourceAuthority = isClinicalStudyLane
      ? explicitAuthority ||
        normalizeSpaces(
          pickNonBlank(record, metadata, [
            "journal_name",
            "meeting_name",
            "publisher",
            "dataSourceName",
            "data_source_name"
          ])
        )
      : explicitAuthority;
    const fullText = cleanFullText(sourceText(record, metadata));
    const snippet = compressSnippet(fullText, lane);

    if (typeof docId !== "string" || !docId.trim()) {
      return { valid: false, reason: "MISSING_DOC_ID" };
    }
    if (!validSplitIndex(splitIndex)) {
      return { valid: false, reason: "INVALID_SPLIT_INDEX" };
    }
    if (!sourceTitle) {
      return { valid: false, reason: "MISSING_SOURCE_TITLE" };
    }
    if (!snippet) {
      return { valid: false, reason: "EMPTY_SNIPPET" };
    }

    return {
      valid: true,
      full_text: fullText,
      record: {
        evidence_id: "",
        lane,
        doc_id: docId,
        split_index: splitIndex,
        type: normalizeSpaces(
          pickNonBlank(record, metadata, ["type", "source_type"])
        ),
        authority: sourceAuthority,
        source_title: sourceTitle,
        source_version: normalizeSpaces(
          pickNonBlank(record, metadata, [
            "source_version",
            "version",
            "year",
            "publish_year",
            "publication_year"
          ])
        ),
        source_section: sourceSection,
        source_url: safeSourceUrl(
          pickNonBlank(record, metadata, [
            "source_url",
            "url",
            "link",
            "sourceUrl"
          ])
        ),
        snippet,
        hard_evidence_type: "",
        reasoning_eligible: false,
        eligibility_class: "ineligible"
      }
    };
  }

  function identifiableStudy(record, fullText) {
    const text = [
      record.source_title,
      record.source_version,
      record.source_section,
      scalarString(fullText) || record.snippet
    ].join(" ");
    const identityText = `${record.source_title} ${record.source_section}`;
    if (
      /(case\s*report|case\s*series|病例报告|病例分享|个案报道|个案报告|we\s+(?:first\s+)?report(?:ed)?\s+(?:a\s+)?cases?|report(?:ed)?\s+cases?)/i.test(
        `${record.source_title} ${record.source_section} ${record.snippet}`
      )
    ) {
      return false;
    }
    const hasRegistry =
      /\bNCT\d{6,8}\b/i.test(text) ||
      /\bChiCTR[-_A-Za-z0-9]*\d{4,}\b/i.test(text) ||
      /\b(?:jRCT|UMIN|ACTRN|ISRCTN|CTR)[-_A-Za-z0-9]*\d{4,}\b/i.test(text);
    const hasIdentity =
      hasRegistry ||
      /(\btrial\b|\bstudy\b|临床试验|随机研究|队列研究)/i.test(
        record.source_title
      );
    const hasDesign =
      /(随机|对照|双盲|开放标签|单臂|队列|前瞻|回顾|phase\s*[i1-4v]+|[一二三四1-4]期|randomi[sz]ed|cohort)/i.test(
        text
      );
    const hasPopulation =
      /(患者|受试者|入组|人群|participants?|patients?|eligible)/i.test(text);
    const hasIntervention =
      /(接受|使用|治疗|联合|单药|方案|治疗组|对照组|versus|\bvs\.?\b|received|treated|treatment|therapy|regimen|intervention)/i.test(
        text
      );
    const hasEndpoint =
      /(主要终点|次要终点|终点|PFS|OS|ORR|DFS|EFS|\bMPR\b|\bpCR\b|\bOR\b|endpoint)/i.test(
        text
      );
    const resultsMatch =
      /(?:^|[\r\n.;。；])\s*(?:results?|结果)\s*(?:[:：]|[\r\n]+|(?=(?:showed|demonstrated|reported|included|enrolled|randomized|显示|表明|提示|截至|共|纳入|入组)))/i.exec(text);
    const resultsWindow = resultsMatch
      ? text.slice(resultsMatch.index, resultsMatch.index + 1200)
      : "";
    const commonStudyTokens = new Set([
      "RESULT", "RESULTS", "TRIAL", "STUDY", "PHASE", "PFS", "OS", "ORR",
      "DFS", "EFS", "HR", "CI", "NSCLC", "SCLC", "ALK", "EGFR", "ROS1",
      "RET", "KRAS", "BRAF", "NTRK", "MET", "HER2", "PDL1", "TKI",
      "III", "IV"
    ]);
    function identityTokens(value) {
      const tokens = [];
      const pattern = /\b([A-Z][A-Z0-9-]{2,24}(?:\s+\d{2,5})?)\b/g;
      let match;
      while ((match = pattern.exec(String(value || ""))) !== null) {
        const token = match[1].replace(/\s+/g, " ").trim().toUpperCase();
        if (!commonStudyTokens.has(token) && !/^\d+$/.test(token)) tokens.push(token);
      }
      return Array.from(new Set(tokens));
    }
    function referencedStudyTokens(value) {
      const tokens = [];
      const pattern = /\b([A-Z][A-Z0-9-]{2,24}(?:\s+\d{2,5})?)\s*(?=(?:(?:trial|study)\b|研究|试验))/gi;
      let match;
      while ((match = pattern.exec(String(value || ""))) !== null) {
        const token = match[1].replace(/\s+/g, " ").trim().toUpperCase();
        if (!commonStudyTokens.has(token) && !/^\d+$/.test(token)) tokens.push(token);
      }
      return Array.from(new Set(tokens));
    }
    const currentStudyTokens = new Set(identityTokens(identityText));
    const priorAttribution =
      /\b(?:prior|previous|previously|earlier)\b|既往|此前|先前|其他(?:研究|试验)|另一项(?:研究|试验)/i;
    const futureOrDesignAction =
      /\b(?:will|shall)\s+(?:be\s+)?(?:enroll|recruit|register|receive|undergo)|\b(?:is|are|was|were)\s+(?:planned|expected|intended|designed)\s+to\s+(?:enroll|recruit|assess|evaluate|receive|undergo)|\b(?:aims?|plans?|intends?)\s+to\s+(?:enroll|recruit|assess|evaluate|receive|undergo)|拟纳入|计划纳入|计划入组|将入组|将招募|将接受|预期纳入|旨在纳入/i;
    const resultSegments = resultsWindow
      .split(/[。！？!?；;\n]+|\.(?:\s+|$)/)
      .map((segment) => segment.trim())
      .filter(Boolean);
    const ownResultSegments = [];
    let resultOwner = "unknown";
    for (const segment of resultSegments) {
      const allTokens = identityTokens(segment);
      const mentionedStudies = referencedStudyTokens(segment);
      const mentionsCurrent =
        allTokens.some((token) => currentStudyTokens.has(token)) ||
        /\b(?:this|our)\s+(?:study|trial)\b|\bwe\s+(?:enrolled|randomized|included|treated)|本研究|该研究/i.test(
          segment
        );
      const mentionsForeignStudy =
        currentStudyTokens.size > 0 &&
        mentionedStudies.length > 0 &&
        !mentionedStudies.some((token) => currentStudyTokens.has(token));

      if (priorAttribution.test(segment) || mentionsForeignStudy) {
        // 所有权持续到明确出现当前研究标识；分号后的裸ORR/PFS不得脱离前句归属。
        resultOwner = "prior";
        continue;
      }
      if (futureOrDesignAction.test(segment)) {
        if (mentionsCurrent) resultOwner = "design";
        continue;
      }
      if (mentionsCurrent) {
        resultOwner = "current";
      } else if (resultOwner === "prior" || resultOwner === "design") {
        continue;
      } else if (resultOwner === "unknown") {
        // Results段首个无他研/未来标识的陈述，按当前记录本研究结果处理。
        resultOwner = "current";
      }
      ownResultSegments.push(segment);
    }
    const ownResultsText = ownResultSegments.join(" ");
    const hasQuantitativeOutcome =
      /(\d+(?:\.\d+)?\s*%|\bHR\s*[=:：]?\s*\d|hazard\s*ratio\s*[=:：]?\s*\d|\b(?:mPFS|mOS|PFS|OS|ORR|DFS|EFS)\b[^。.;]{0,40}\d|中位[^。；;]{0,30}\d+|置信区间|95%\s*CI)/i.test(
        ownResultsText
      );
    const hasCompletedCohort =
      /(?:本研究|该研究)?(?:纳入|入组|随机分配|共)\s*(?:了)?\s*\d+\s*例|(?:enrolled|randomized|included)\s+\d+\s+(?:patients?|participants?)|\d+\s+(?:patients?|participants?)\s+(?:were\s+)?(?:enrolled|randomized|included)/i.test(
        ownResultsText
      );
    const hasOwnStudyResults =
      Boolean(resultsMatch) && (hasQuantitativeOutcome || hasCompletedCohort);
    const designOnlyIdentity =
      /(study\s+to\s+assess|trial\s+design|study\s+design|rationale\s+and\s+(?:study\s+)?design|\bprotocol\b)/i.test(
        identityText
      );
    const futureStudyAction =
      futureOrDesignAction.test(text);
    const explicitlyNoOwnResults =
      /(no\s+(?:[A-Z][A-Z0-9-]*\s+)?(?:study\s+)?(?:results?|outcomes?|findings)\s+(?:are|were)\s+available|尚无(?:本研究|该研究)?(?:结果|结局)|(?:本研究|该研究)(?:结果|结局)尚未(?:公布|报告)|未报告(?:本研究|该研究)(?:结果|结局))/i.test(
        text
      );
    if (
      designOnlyIdentity ||
      explicitlyNoOwnResults ||
      (futureStudyAction && !hasOwnStudyResults)
    ) {
      return false;
    }
    return Boolean(
      hasIdentity &&
        hasDesign &&
        hasPopulation &&
        hasIntervention &&
        hasEndpoint &&
        hasOwnStudyResults
    );
  }

  function hardEvidenceType(record, fullText) {
    if (
      record.type.toLowerCase() === "guideline" &&
      Boolean(record.authority) &&
      Boolean(record.source_title)
    ) {
      return "指南";
    }
    if (
      (record.lane === "clinical_study_initial" ||
        record.lane === "clinical_study_supplement") &&
      record.type.toLowerCase() !== "guideline" &&
      identifiableStudy(record, fullText)
    ) {
      return "临床研究";
    }
    return "";
  }

  function eligibleSecondaryForReasoning(record) {
    const type = record.type.toLowerCase().replace(/[\s-]+/g, "_");
    const identity = `${record.source_title} ${record.authority}`;
    const forbidden =
      /(病例分享|个案|case\s*report|会议新闻|会议报道|媒体|新闻|解读|述评|观点|医生文章|科普)/i.test(
        identity
      );
    const eligibleType =
      /(systematic_review|meta_analysis|evidence_review|society_education|official_education|educational_resource)/i.test(
        type
      );
    const eligibleIdentity =
      /(系统综述|meta[_ -]?analysis|systematic\s+review|循证综述|学会教育|official\s+education|educational\s+resource)/i.test(
        identity
      );
    return Boolean(
      !forbidden &&
        eligibleType &&
        eligibleIdentity &&
        record.authority &&
        record.source_title &&
        record.snippet
    );
  }

  const prefixCounters = { GA: 0, GB: 0, CS: 0, IR: 0 };
  const seenLocators = new Set();
  const records = [];
  const laneEvidenceIds = {};
  const dropped = [];
  const inputCounts = {};
  const retrievalErrors = RETRIEVAL_ERROR_FIELDS.flatMap(({ key, lane }) => {
    const message = normalizeSpaces(source[key]);
    return message ? [{ lane, message: message.slice(0, 500) }] : [];
  });
  const retrievalHealth = {
    ok: retrievalErrors.length === 0,
    errors: retrievalErrors
  };

  for (const definition of LANE_DEFINITIONS) {
    const rawRecords = toRecords(source[definition.key]);
    inputCounts[definition.key] = rawRecords.length;
    laneEvidenceIds[definition.key] = [];
    let keptInLane = 0;

    for (let index = 0; index < rawRecords.length; index++) {
      if (keptInLane >= definition.limit) {
        dropped.push({
          lane: definition.key,
          index,
          reason: "LANE_LIMIT"
        });
        continue;
      }
      const normalized = normalizeRecord(rawRecords[index], definition.key);
      if (!normalized.valid) {
        dropped.push({ lane: definition.key, index, reason: normalized.reason });
        continue;
      }
      const record = normalized.record;
      record.hard_evidence_type = hardEvidenceType(record, normalized.full_text);
      record.reasoning_eligible = Boolean(
        record.hard_evidence_type || eligibleSecondaryForReasoning(record)
      );
      record.eligibility_class = record.hard_evidence_type
        ? "hard"
        : record.reasoning_eligible
          ? "clinical_reasoning_secondary"
          : "ineligible";
      if (!record.reasoning_eligible) {
        dropped.push({
          lane: definition.key,
          index,
          reason: "INELIGIBLE_SOURCE",
          locator: locatorKey(record.doc_id, record.split_index)
        });
        continue;
      }
      const locator = locatorKey(record.doc_id, record.split_index);
      if (seenLocators.has(locator)) {
        dropped.push({
          lane: definition.key,
          index,
          reason: "DUPLICATE_LOCATOR",
          locator
        });
        continue;
      }

      seenLocators.add(locator);
      prefixCounters[definition.prefix] += 1;
      record.evidence_id = `${definition.prefix}${String(
        prefixCounters[definition.prefix]
      ).padStart(2, "0")}`;
      records.push(record);
      laneEvidenceIds[definition.key].push(record.evidence_id);
      keptInLane += 1;
    }
  }

  const initialStudyCount = records.filter(
    (record) =>
      record.lane === "clinical_study_initial" &&
      record.hard_evidence_type === "临床研究"
  ).length;
  const supplementStudyCount = records.filter(
    (record) =>
      record.lane === "clinical_study_supplement" &&
      record.hard_evidence_type === "临床研究"
  ).length;
  const hardCandidateCount = records.filter((record) =>
    ["指南", "临床研究"].includes(record.hard_evidence_type)
  ).length;
  const eligibleCandidateCount = records.filter(
    (record) => record.reasoning_eligible === true
  ).length;
  function primaryDecisionDomain(record) {
    const text = `${record.source_title} ${record.source_section} ${record.snippet}`;
    if (record.lane === "irae_a" || record.lane === "irae_b") return "toxicity";
    if (/(鉴别诊断|病理诊断|小活检|再次取材|重新取材|病理复核|重新分期|分期评估)/i.test(text)) {
      return "diagnosis_staging";
    }
    if (/(寡进展|CNS\s*进展|脑转移|广泛进展|疾病进展|复发|耐药|后线|局部治疗)/i.test(text)) {
      return "progression_later_line";
    }
    if (/(分子检测|基因检测|融合检测|ALK.{0,16}检测|PD-?L1.{0,16}检测|免疫组织化学|\bIHC\b)/i.test(text)) {
      return "molecular_testing";
    }
    if (/(可切除|手术时机|根治性手术|R0\s*切除|多学科|\bMDT\b|病理缓解|完全病理缓解|主要病理缓解|\bMPR\b|\bpCR\b|瘤床)/i.test(text)) {
      return "local_operative";
    }
    if (/(术后|辅助治疗|长期随访|复查随访)/i.test(text)) {
      return "postoperative_followup";
    }
    if (/(一线治疗|系统治疗|靶向治疗|免疫治疗|化学治疗|化疗|\bTKI\b)/i.test(text)) {
      return "systemic_treatment";
    }
    return "other";
  }
  const decisionDomains = Array.from(
    new Set(records.filter((record) => record.reasoning_eligible).map(primaryDecisionDomain))
  );
  const identifiableStudyCount = initialStudyCount + supplementStudyCount;
  // 容量按互不相同的临床决策域估算；合格原始研究可额外支持研究解读题。
  // 不再仅凭“同一 locator 最多可复用两次”把同质分块虚增成五题。
  const estimatedQuestionCapacity = Math.min(
    5,
    eligibleCandidateCount,
    decisionDomains.length + identifiableStudyCount
  );
  const insufficientForFive =
    hardCandidateCount < 2 || estimatedQuestionCapacity < 5;
  const needsClinicalSupplement = retrievalHealth.ok && insufficientForFive;
  const supplementReasons = [];
  if (!retrievalHealth.ok) {
    supplementReasons.push("检索链存在技术错误，禁止把技术空结果送入研究补检或判为医学证据不足");
  }
  if (hardCandidateCount < 2) {
    supplementReasons.push("硬证据候选少于2条");
  }
  if (estimatedQuestionCapacity < 5) {
    supplementReasons.push("压缩证据池的理论五题容量不足");
  }

  const keptCounts = Object.fromEntries(
    Object.entries(laneEvidenceIds).map(([lane, ids]) => [lane, ids.length])
  );
  const compressionReport = {
    input_counts: inputCounts,
    kept_counts: keptCounts,
    kept_total: records.length,
    dropped_total: dropped.length,
    dropped
  };
  const capacityReport = {
    hard_candidate_count: hardCandidateCount,
    eligible_candidate_count: eligibleCandidateCount,
    decision_domain_count: decisionDomains.length,
    decision_domains: decisionDomains,
    estimated_question_capacity: estimatedQuestionCapacity,
    evidence_pool_insufficient_for_five: insufficientForFive,
    identifiable_initial_study_count: initialStudyCount,
    identifiable_supplement_study_count: supplementStudyCount
  };
  const evidencePool = {
    contract_version: "1.2",
    publication_schema_version: "1.1",
    limits: LANE_LIMITS,
    records,
    lanes: laneEvidenceIds,
    retrieval_health: retrievalHealth,
    capacity_report: capacityReport,
    compression_report: compressionReport
  };

  return {
    evidence_pool: evidencePool,
    evidence_pool_json: JSON.stringify(evidencePool),
    retrieval_health_ok: retrievalHealth.ok,
    retrieval_health: retrievalHealth,
    retrieval_errors: retrievalErrors,
    needs_clinical_supplement: needsClinicalSupplement,
    supplement_decision: !retrievalHealth.ok
      ? "BLOCKED_TECHNICAL"
      : insufficientForFive
        ? "TRIGGER"
        : "SKIP",
    supplement_reason: supplementReasons.join("；"),
    evidence_pool_insufficient_for_five: insufficientForFive,
    estimated_question_capacity: estimatedQuestionCapacity,
    hard_candidate_count: hardCandidateCount,
    eligible_candidate_count: eligibleCandidateCount,
    identifiable_initial_study_count: initialStudyCount,
    identifiable_supplement_study_count: supplementStudyCount,
    compression_report: compressionReport,
    compression_report_json: JSON.stringify(compressionReport)
  };
}

function main(inputs) {
  const source = inputs && typeof inputs === "object" ? inputs : {};
  const LANE_DEFINITIONS = [
    { key: "guideline_a_staging", prefix: "GS", limit: 4 },
    { key: "guideline_a", prefix: "GA", limit: 4 },
    { key: "guideline_b", prefix: "GB", limit: 6 },
    { key: "clinical_study_initial", prefix: "CS", limit: 5 },
    { key: "clinical_study_supplement", prefix: "CS", limit: 3 },
    { key: "irae_a", prefix: "IR", limit: 4 },
    { key: "irae_b", prefix: "IR", limit: 4 }
  ];
  const LANE_LIMITS = Object.fromEntries(
    LANE_DEFINITIONS.map((item) => [item.key, item.limit])
  );
  const RETRIEVAL_ERROR_FIELDS = [
    { key: "guideline_a_staging_error", lane: "guideline_a_staging" },
    { key: "guideline_a_staging_system_error", lane: "guideline_a_staging" },
    { key: "guideline_a_error", lane: "guideline_a" },
    { key: "guideline_a_system_error", lane: "guideline_a" },
    { key: "guideline_b_error", lane: "guideline_b" },
    { key: "guideline_b_system_error", lane: "guideline_b" },
    { key: "clinical_study_initial_error", lane: "clinical_study_initial" },
    { key: "clinical_study_initial_system_error", lane: "clinical_study_initial" },
    { key: "clinical_study_supplement_error", lane: "clinical_study_supplement" },
    { key: "clinical_study_supplement_system_error", lane: "clinical_study_supplement" },
    { key: "irae_a_error", lane: "irae_a" },
    { key: "irae_a_system_error", lane: "irae_a" },
    { key: "irae_b_error", lane: "irae_b" },
    { key: "irae_b_system_error", lane: "irae_b" },
    { key: "knowledge_search_error", lane: "knowledge_search" }
  ];
  const CONTENT_KEYS = new Set([
    "snippet",
    "text",
    "content",
    "pagecontent",
    "chunk",
    "q",
    "a",
    "answer"
  ]);

  function hasOwn(object, key) {
    return Boolean(object && Object.prototype.hasOwnProperty.call(object, key));
  }

  function parseMaybe(value) {
    if (typeof value !== "string") return value;
    const text = value.trim();
    if (!text) return [];
    try {
      return JSON.parse(text);
    } catch (_) {
      return value;
    }
  }

  function asObject(value) {
    const parsed = parseMaybe(value);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed)
      ? parsed
      : {};
  }

  function hasRecordShape(value) {
    if (!value || typeof value !== "object" || Array.isArray(value)) return false;
    return Object.keys(value).some((key) =>
      /^(doc_?id|docId|documentId|dataId|split_?index|splitIndex|chunkIndex|snippet|text|content|pageContent)$/i.test(
        key
      )
    );
  }

  function toRecords(input) {
    const value = parseMaybe(input);
    if (Array.isArray(value)) {
      return value.flatMap((item) => toRecords(item));
    }
    if (!value || typeof value !== "object") return [];
    if (hasRecordShape(value)) return [value];
    for (const key of [
      "records",
      "results",
      "result",
      "list",
      "data",
      "searchResults",
      "searchResult",
      "chunks"
    ]) {
      if (!hasOwn(value, key)) continue;
      const records = toRecords(value[key]);
      if (records.length > 0) return records;
    }
    return [];
  }

  function metadataOf(record) {
    return asObject(record && (record.metadata || record.metaData || record.meta));
  }

  function pick(record, metadata, keys) {
    for (const key of keys) {
      if (hasOwn(record, key) && record[key] !== null && record[key] !== undefined) {
        return record[key];
      }
      if (
        hasOwn(metadata, key) &&
        metadata[key] !== null &&
        metadata[key] !== undefined
      ) {
        return metadata[key];
      }
    }
    return "";
  }

  function pickNonBlank(record, metadata, keys) {
    for (const key of keys) {
      for (const container of [record, metadata]) {
        if (!hasOwn(container, key)) continue;
        const value = container[key];
        if (value === null || value === undefined) continue;
        if (typeof value === "string" && !value.trim()) continue;
        return value;
      }
    }
    return "";
  }

  function scalarString(value) {
    if (value === null || value === undefined) return "";
    if (typeof value === "string") return value;
    if (typeof value === "number" || typeof value === "boolean") {
      return String(value);
    }
    return "";
  }

  function normalizeSpaces(value) {
    return scalarString(value)
      .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, " ")
      .replace(/\uFFFD/g, "")
      .replace(/\s+/g, " ")
      .trim();
  }

  function decodeHtml(text) {
    const named = {
      amp: "&",
      lt: "<",
      gt: ">",
      quot: '"',
      apos: "'",
      nbsp: " "
    };
    return text
      .replace(/&([a-z]+);/gi, (match, name) =>
        hasOwn(named, name.toLowerCase()) ? named[name.toLowerCase()] : match
      )
      .replace(/&#(\d+);/g, (_, code) => {
        const value = Number(code);
        return Number.isFinite(value) ? String.fromCodePoint(value) : "";
      })
      .replace(/&#x([0-9a-f]+);/gi, (_, code) => {
        const value = parseInt(code, 16);
        return Number.isFinite(value) ? String.fromCodePoint(value) : "";
      });
  }

  function cleanFullText(value) {
    let text = scalarString(value);
    text = text
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ")
      .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ")
      .replace(/<(?:br|\/p|\/li|\/div|\/h[1-6])\s*\/?>/gi, "\n")
      .replace(/<[^>]+>/g, " ");
    text = decodeHtml(text)
      .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, " ")
      .replace(/\uFFFD/g, "")
      .replace(/[\t\f\v]+/g, " ")
      .replace(/ *\n+ */g, "\n")
      .replace(/ {2,}/g, " ")
      .trim();

    const segments = text.match(/[^。！？!?；;\n]+[。！？!?；;]?/g) || [];
    const seen = new Set();
    const unique = [];
    for (const raw of segments) {
      const segment = raw.replace(/\s+/g, " ").trim();
      const key = segment.replace(/[\s。！？!?；;，,、]/g, "").toLowerCase();
      if (!segment || !key || seen.has(key)) continue;
      seen.add(key);
      unique.push(segment);
    }
    // 保留段落边界，避免“Results/结果”标题与下一句黏连后无法识别。
    return unique.join("\n").trim();
  }

  function compressSnippet(fullText, lane) {
    const text = scalarString(fullText).trim();
    if (text.length <= 1000) return text;
    if (lane !== "clinical_study_initial" && lane !== "clinical_study_supplement") {
      return text.slice(0, 1000).trim();
    }

    // 临床研究长摘要的结果段常位于Methods之后。身份判定使用未截断全文；
    // 模型可见snippet则保留题名前文、Results/结果及Conclusion/结论附近文本。
    const windows = [];
    const addWindow = (start, length) => {
      const safeStart = Math.max(0, Math.min(text.length, start));
      const value = text.slice(safeStart, safeStart + length).trim();
      if (value && !windows.includes(value)) windows.push(value);
    };
    addWindow(0, 300);
    const resultsMatch = /(?:^|[\s.;。；])(?:results?|结果)\s*[:：]?/i.exec(text);
    if (resultsMatch) addWindow(Math.max(0, resultsMatch.index - 80), 560);
    const conclusionMatch = /(?:^|[\s.;。；])(?:conclusions?|结论)\s*[:：]?/i.exec(text);
    if (conclusionMatch) addWindow(Math.max(0, conclusionMatch.index - 40), 260);
    if (windows.length === 1) addWindow(Math.max(0, text.length - 650), 650);
    return windows.join("…").slice(0, 1000).trim();
  }

  function sourceText(record, metadata) {
    const direct = pickNonBlank(record, metadata, [
      "snippet",
      "text",
      "content",
      "pageContent",
      "chunk"
    ]);
    if (scalarString(direct).trim()) return direct;
    const q = scalarString(
      pickNonBlank(record, metadata, ["q", "question"])
    ).trim();
    const a = scalarString(
      pickNonBlank(record, metadata, ["a", "answer"])
    ).trim();
    return [q, a].filter(Boolean).join("\n");
  }

  function safeSourceUrl(value) {
    const text = normalizeSpaces(value);
    return /^https?:\/\/\S+$/i.test(text) ? text : "";
  }

  function locatorKey(docId, splitIndex) {
    return `${String(docId)}::${String(splitIndex)}`;
  }

  function validSplitIndex(value) {
    // 发布合同要求非负整数；不把字符串静默改型，以免改变来源定位。
    return Number.isInteger(value) && value >= 0;
  }

  function normalizeRecord(rawRecord, lane) {
    const record = rawRecord && typeof rawRecord === "object" ? rawRecord : {};
    const metadata = metadataOf(record);
    const isClinicalStudyLane =
      lane === "clinical_study_initial" || lane === "clinical_study_supplement";
    const docId = pickNonBlank(record, metadata, [
      "doc_id",
      "docId",
      "document_id",
      "documentId",
      "dataId",
      "sourceId"
    ]);
    const splitIndex = pickNonBlank(record, metadata, [
      "split_index",
      "splitIndex",
      "chunk_index",
      "chunkIndex",
      "index"
    ]);
    const recordTitle = normalizeSpaces(record.title);
    const metadataTitle = normalizeSpaces(metadata.title);
    const studyName = normalizeSpaces(
      pickNonBlank(record, metadata, ["study_name", "studyName"])
    );
    const guidelineName = normalizeSpaces(
      pickNonBlank(record, metadata, ["guideline_name", "guidelineName"])
    );
    const dataSourceName = normalizeSpaces(
      pickNonBlank(record, metadata, ["dataSourceName", "data_source_name"])
    );
    const namedSource = normalizeSpaces(
      pickNonBlank(record, metadata, [
        "formal_title",
        "formalTitle",
        "source_title",
        "sourceName",
        "documentTitle",
        "publicationTitle"
      ])
    );
    const explicitSection = normalizeSpaces(
      pickNonBlank(record, metadata, [
        "source_section",
        "section",
        "heading",
        "chapter",
        "chunk_title",
        "chunkTitle"
      ])
    );
    // 临床研究的dataSourceName常是期刊名；正式研究/文章题名优先来自
    // study_name、metaData.title或record.title。record.title同时保留为分块章节。
    const sourceTitle = isClinicalStudyLane
      ? studyName || metadataTitle || recordTitle || namedSource || dataSourceName
      : dataSourceName || guidelineName || namedSource;
    const sourceSection = isClinicalStudyLane
      ? explicitSection || recordTitle
      : explicitSection || recordTitle || metadataTitle;
    const explicitAuthority = normalizeSpaces(
      pickNonBlank(record, metadata, [
        "authority",
        "issuing_authority",
        "organization"
      ])
    );
    const sourceAuthority = isClinicalStudyLane
      ? explicitAuthority ||
        normalizeSpaces(
          pickNonBlank(record, metadata, [
            "journal_name",
            "meeting_name",
            "publisher",
            "dataSourceName",
            "data_source_name"
          ])
        )
      : explicitAuthority;
    const fullText = cleanFullText(sourceText(record, metadata));
    const snippet = compressSnippet(fullText, lane);

    if (typeof docId !== "string" || !docId.trim()) {
      return { valid: false, reason: "MISSING_DOC_ID" };
    }
    if (!validSplitIndex(splitIndex)) {
      return { valid: false, reason: "INVALID_SPLIT_INDEX" };
    }
    if (!sourceTitle) {
      return { valid: false, reason: "MISSING_SOURCE_TITLE" };
    }
    if (!snippet) {
      return { valid: false, reason: "EMPTY_SNIPPET" };
    }

    return {
      valid: true,
      full_text: fullText,
      record: {
        evidence_id: "",
        lane,
        doc_id: docId,
        split_index: splitIndex,
        type: normalizeSpaces(
          pickNonBlank(record, metadata, ["type", "source_type"])
        ),
        authority: sourceAuthority,
        source_title: sourceTitle,
        source_version: normalizeSpaces(
          pickNonBlank(record, metadata, [
            "source_version",
            "version",
            "year",
            "publish_year",
            "publication_year"
          ])
        ),
        source_section: sourceSection,
        source_url: safeSourceUrl(
          pickNonBlank(record, metadata, [
            "source_url",
            "url",
            "link",
            "sourceUrl"
          ])
        ),
        snippet,
        hard_evidence_type: "",
        reasoning_eligible: false,
        eligibility_class: "ineligible"
      }
    };
  }

  function identifiableStudy(record, fullText) {
    const text = [
      record.source_title,
      record.source_version,
      record.source_section,
      scalarString(fullText) || record.snippet
    ].join(" ");
    const identityText = `${record.source_title} ${record.source_section}`;
    if (
      /(case\s*report|case\s*series|病例报告|病例分享|个案报道|个案报告|we\s+(?:first\s+)?report(?:ed)?\s+(?:a\s+)?cases?|report(?:ed)?\s+cases?)/i.test(
        `${record.source_title} ${record.source_section} ${record.snippet}`
      )
    ) {
      return false;
    }
    const hasRegistry =
      /\bNCT\d{6,8}\b/i.test(text) ||
      /\bChiCTR[-_A-Za-z0-9]*\d{4,}\b/i.test(text) ||
      /\b(?:jRCT|UMIN|ACTRN|ISRCTN|CTR)[-_A-Za-z0-9]*\d{4,}\b/i.test(text);
    const hasIdentity =
      hasRegistry ||
      /(\btrial\b|\bstudy\b|临床试验|随机研究|队列研究)/i.test(
        record.source_title
      );
    const hasDesign =
      /(随机|对照|双盲|开放标签|单臂|队列|前瞻|回顾|phase\s*[i1-4v]+|[一二三四1-4]期|randomi[sz]ed|cohort)/i.test(
        text
      );
    const hasPopulation =
      /(患者|受试者|入组|人群|participants?|patients?|eligible)/i.test(text);
    const hasIntervention =
      /(接受|使用|治疗|联合|单药|方案|治疗组|对照组|versus|\bvs\.?\b|received|treated|treatment|therapy|regimen|intervention)/i.test(
        text
      );
    const hasEndpoint =
      /(主要终点|次要终点|终点|PFS|OS|ORR|DFS|EFS|\bMPR\b|\bpCR\b|\bOR\b|endpoint)/i.test(
        text
      );
    const resultsMatch =
      /(?:^|[\r\n.;。；])\s*(?:results?|结果)\s*(?:[:：]|[\r\n]+|(?=(?:showed|demonstrated|reported|included|enrolled|randomized|显示|表明|提示|截至|共|纳入|入组)))/i.exec(text);
    const resultsWindow = resultsMatch
      ? text.slice(resultsMatch.index, resultsMatch.index + 1200)
      : "";
    const commonStudyTokens = new Set([
      "RESULT", "RESULTS", "TRIAL", "STUDY", "PHASE", "PFS", "OS", "ORR",
      "DFS", "EFS", "HR", "CI", "NSCLC", "SCLC", "ALK", "EGFR", "ROS1",
      "RET", "KRAS", "BRAF", "NTRK", "MET", "HER2", "PDL1", "TKI",
      "III", "IV"
    ]);
    function identityTokens(value) {
      const tokens = [];
      const pattern = /\b([A-Z][A-Z0-9-]{2,24}(?:\s+\d{2,5})?)\b/g;
      let match;
      while ((match = pattern.exec(String(value || ""))) !== null) {
        const token = match[1].replace(/\s+/g, " ").trim().toUpperCase();
        if (!commonStudyTokens.has(token) && !/^\d+$/.test(token)) tokens.push(token);
      }
      return Array.from(new Set(tokens));
    }
    function referencedStudyTokens(value) {
      const tokens = [];
      const pattern = /\b([A-Z][A-Z0-9-]{2,24}(?:\s+\d{2,5})?)\s*(?=(?:(?:trial|study)\b|研究|试验))/gi;
      let match;
      while ((match = pattern.exec(String(value || ""))) !== null) {
        const token = match[1].replace(/\s+/g, " ").trim().toUpperCase();
        if (!commonStudyTokens.has(token) && !/^\d+$/.test(token)) tokens.push(token);
      }
      return Array.from(new Set(tokens));
    }
    const currentStudyTokens = new Set(identityTokens(identityText));
    const priorAttribution =
      /\b(?:prior|previous|previously|earlier)\b|既往|此前|先前|其他(?:研究|试验)|另一项(?:研究|试验)/i;
    const futureOrDesignAction =
      /\b(?:will|shall)\s+(?:be\s+)?(?:enroll|recruit|register|receive|undergo)|\b(?:is|are|was|were)\s+(?:planned|expected|intended|designed)\s+to\s+(?:enroll|recruit|assess|evaluate|receive|undergo)|\b(?:aims?|plans?|intends?)\s+to\s+(?:enroll|recruit|assess|evaluate|receive|undergo)|拟纳入|计划纳入|计划入组|将入组|将招募|将接受|预期纳入|旨在纳入/i;
    const resultSegments = resultsWindow
      .split(/[。！？!?；;\n]+|\.(?:\s+|$)/)
      .map((segment) => segment.trim())
      .filter(Boolean);
    const ownResultSegments = [];
    let resultOwner = "unknown";
    for (const segment of resultSegments) {
      const allTokens = identityTokens(segment);
      const mentionedStudies = referencedStudyTokens(segment);
      const mentionsCurrent =
        allTokens.some((token) => currentStudyTokens.has(token)) ||
        /\b(?:this|our)\s+(?:study|trial)\b|\bwe\s+(?:enrolled|randomized|included|treated)|本研究|该研究/i.test(
          segment
        );
      const mentionsForeignStudy =
        currentStudyTokens.size > 0 &&
        mentionedStudies.length > 0 &&
        !mentionedStudies.some((token) => currentStudyTokens.has(token));

      if (priorAttribution.test(segment) || mentionsForeignStudy) {
        // 所有权持续到明确出现当前研究标识；分号后的裸ORR/PFS不得脱离前句归属。
        resultOwner = "prior";
        continue;
      }
      if (futureOrDesignAction.test(segment)) {
        if (mentionsCurrent) resultOwner = "design";
        continue;
      }
      if (mentionsCurrent) {
        resultOwner = "current";
      } else if (resultOwner === "prior" || resultOwner === "design") {
        continue;
      } else if (resultOwner === "unknown") {
        // Results段首个无他研/未来标识的陈述，按当前记录本研究结果处理。
        resultOwner = "current";
      }
      ownResultSegments.push(segment);
    }
    const ownResultsText = ownResultSegments.join(" ");
    const hasQuantitativeOutcome =
      /(\d+(?:\.\d+)?\s*%|\bHR\s*[=:：]?\s*\d|hazard\s*ratio\s*[=:：]?\s*\d|\b(?:mPFS|mOS|PFS|OS|ORR|DFS|EFS)\b[^。.;]{0,40}\d|中位[^。；;]{0,30}\d+|置信区间|95%\s*CI)/i.test(
        ownResultsText
      );
    const hasCompletedCohort =
      /(?:本研究|该研究)?(?:纳入|入组|随机分配|共)\s*(?:了)?\s*\d+\s*例|(?:enrolled|randomized|included)\s+\d+\s+(?:patients?|participants?)|\d+\s+(?:patients?|participants?)\s+(?:were\s+)?(?:enrolled|randomized|included)/i.test(
        ownResultsText
      );
    const hasOwnStudyResults =
      Boolean(resultsMatch) && (hasQuantitativeOutcome || hasCompletedCohort);
    const designOnlyIdentity =
      /(study\s+to\s+assess|trial\s+design|study\s+design|rationale\s+and\s+(?:study\s+)?design|\bprotocol\b)/i.test(
        identityText
      );
    const futureStudyAction =
      futureOrDesignAction.test(text);
    const explicitlyNoOwnResults =
      /(no\s+(?:[A-Z][A-Z0-9-]*\s+)?(?:study\s+)?(?:results?|outcomes?|findings)\s+(?:are|were)\s+available|尚无(?:本研究|该研究)?(?:结果|结局)|(?:本研究|该研究)(?:结果|结局)尚未(?:公布|报告)|未报告(?:本研究|该研究)(?:结果|结局))/i.test(
        text
      );
    if (
      designOnlyIdentity ||
      explicitlyNoOwnResults ||
      (futureStudyAction && !hasOwnStudyResults)
    ) {
      return false;
    }
    return Boolean(
      hasIdentity &&
        hasDesign &&
        hasPopulation &&
        hasIntervention &&
        hasEndpoint &&
        hasOwnStudyResults
    );
  }

  function hardEvidenceType(record, fullText) {
    if (
      record.type.toLowerCase() === "guideline" &&
      Boolean(record.authority) &&
      Boolean(record.source_title)
    ) {
      return "指南";
    }
    if (
      (record.lane === "clinical_study_initial" ||
        record.lane === "clinical_study_supplement") &&
      record.type.toLowerCase() !== "guideline" &&
      identifiableStudy(record, fullText)
    ) {
      return "临床研究";
    }
    return "";
  }

  function eligibleSecondaryForReasoning(record) {
    const type = record.type.toLowerCase().replace(/[\s-]+/g, "_");
    const identity = `${record.source_title} ${record.authority}`;
    const forbidden =
      /(病例分享|个案|case\s*report|会议新闻|会议报道|媒体|新闻|解读|述评|观点|医生文章|科普)/i.test(
        identity
      );
    const eligibleType =
      /(systematic_review|meta_analysis|evidence_review|society_education|official_education|educational_resource)/i.test(
        type
      );
    const eligibleIdentity =
      /(系统综述|meta[_ -]?analysis|systematic\s+review|循证综述|学会教育|official\s+education|educational\s+resource)/i.test(
        identity
      );
    return Boolean(
      !forbidden &&
        eligibleType &&
        eligibleIdentity &&
        record.authority &&
        record.source_title &&
        record.snippet
    );
  }

  function eligibleForConfiguredLane(record) {
    if (record.lane !== "guideline_a_staging") return true;

    const text = `${record.source_title} ${record.source_section} ${record.snippet}`;
    if (/(驱动基因阴性|儿童|青少年|pediatric)/i.test(text)) return false;
    if (/(术后病理评估|新辅助.{0,20}术后|\bpCR\b|\bMPR\b|\bypTNM\b)/i.test(text)) {
      return false;
    }

    return /(?:EBUS|CP-EBUS|mediastinoscopy|纵隔镜|淋巴结.{0,60}(?:分期|取样|采样|清扫|活检|组织学验证)|(?:分期|staging).{0,60}(?:淋巴结|lymph|nodal|mediastinal|hilar)|(?:mediastinal|hilar).{0,80}(?:sampling|dissection|staging))/i.test(
      text
    );
  }

  const prefixCounters = { GS: 0, GA: 0, GB: 0, CS: 0, IR: 0 };
  const seenLocators = new Set();
  const records = [];
  const laneEvidenceIds = {};
  const dropped = [];
  const inputCounts = {};
  const retrievalErrors = RETRIEVAL_ERROR_FIELDS.flatMap(({ key, lane }) => {
    const message = normalizeSpaces(source[key]);
    return message ? [{ lane, message: message.slice(0, 500) }] : [];
  });
  const retrievalHealth = {
    ok: retrievalErrors.length === 0,
    errors: retrievalErrors
  };

  for (const definition of LANE_DEFINITIONS) {
    const rawRecords = toRecords(source[definition.key]);
    inputCounts[definition.key] = rawRecords.length;
    laneEvidenceIds[definition.key] = [];
    let keptInLane = 0;

    for (let index = 0; index < rawRecords.length; index++) {
      if (keptInLane >= definition.limit) {
        dropped.push({
          lane: definition.key,
          index,
          reason: "LANE_LIMIT"
        });
        continue;
      }
      const normalized = normalizeRecord(rawRecords[index], definition.key);
      if (!normalized.valid) {
        dropped.push({ lane: definition.key, index, reason: normalized.reason });
        continue;
      }
      const record = normalized.record;
      record.hard_evidence_type = hardEvidenceType(record, normalized.full_text);
      if (!eligibleForConfiguredLane(record)) {
        dropped.push({
          lane: definition.key,
          index,
          reason: "LANE_CONTENT_MISMATCH",
          locator: locatorKey(record.doc_id, record.split_index)
        });
        continue;
      }
      record.reasoning_eligible = Boolean(
        record.hard_evidence_type || eligibleSecondaryForReasoning(record)
      );
      record.eligibility_class = record.hard_evidence_type
        ? "hard"
        : record.reasoning_eligible
          ? "clinical_reasoning_secondary"
          : "ineligible";
      if (!record.reasoning_eligible) {
        dropped.push({
          lane: definition.key,
          index,
          reason: "INELIGIBLE_SOURCE",
          locator: locatorKey(record.doc_id, record.split_index)
        });
        continue;
      }
      const locator = locatorKey(record.doc_id, record.split_index);
      if (seenLocators.has(locator)) {
        dropped.push({
          lane: definition.key,
          index,
          reason: "DUPLICATE_LOCATOR",
          locator
        });
        continue;
      }

      seenLocators.add(locator);
      prefixCounters[definition.prefix] += 1;
      record.evidence_id = `${definition.prefix}${String(
        prefixCounters[definition.prefix]
      ).padStart(2, "0")}`;
      records.push(record);
      laneEvidenceIds[definition.key].push(record.evidence_id);
      keptInLane += 1;
    }
  }

  const initialStudyCount = records.filter(
    (record) =>
      record.lane === "clinical_study_initial" &&
      record.hard_evidence_type === "临床研究"
  ).length;
  const supplementStudyCount = records.filter(
    (record) =>
      record.lane === "clinical_study_supplement" &&
      record.hard_evidence_type === "临床研究"
  ).length;
  const hardCandidateCount = records.filter((record) =>
    ["指南", "临床研究"].includes(record.hard_evidence_type)
  ).length;
  const eligibleCandidateCount = records.filter(
    (record) => record.reasoning_eligible === true
  ).length;
  function primaryDecisionDomain(record) {
    const text = `${record.source_title} ${record.source_section} ${record.snippet}`;
    if (record.lane === "irae_a" || record.lane === "irae_b") return "toxicity";
    if (/(鉴别诊断|病理诊断|小活检|再次取材|重新取材|病理复核|重新分期|分期评估|临床分期|淋巴结分期|纵隔镜|EBUS|\bstaging\b|mediastinoscopy)/i.test(text)) {
      return "diagnosis_staging";
    }
    if (/(寡进展|CNS\s*进展|脑转移|广泛进展|疾病进展|复发|耐药|后线|局部治疗)/i.test(text)) {
      return "progression_later_line";
    }
    if (/(分子检测|基因检测|融合检测|ALK.{0,16}检测|PD-?L1.{0,16}检测|免疫组织化学|\bIHC\b)/i.test(text)) {
      return "molecular_testing";
    }
    if (/(可切除|手术时机|根治性手术|R0\s*切除|多学科|\bMDT\b|病理缓解|完全病理缓解|主要病理缓解|\bMPR\b|\bpCR\b|瘤床)/i.test(text)) {
      return "local_operative";
    }
    if (/(术后|辅助治疗|长期随访|复查随访)/i.test(text)) {
      return "postoperative_followup";
    }
    if (/(一线治疗|系统治疗|靶向治疗|免疫治疗|化学治疗|化疗|\bTKI\b)/i.test(text)) {
      return "systemic_treatment";
    }
    return "other";
  }
  const decisionDomains = Array.from(
    new Set(records.filter((record) => record.reasoning_eligible).map(primaryDecisionDomain))
  );
  const identifiableStudyCount = initialStudyCount + supplementStudyCount;
  // 容量按互不相同的临床决策域估算；合格原始研究可额外支持研究解读题。
  // 不再仅凭“同一 locator 最多可复用两次”把同质分块虚增成五题。
  const estimatedQuestionCapacity = Math.min(
    5,
    eligibleCandidateCount,
    decisionDomains.length + identifiableStudyCount
  );
  const insufficientForFive =
    hardCandidateCount < 2 || estimatedQuestionCapacity < 5;
  const needsClinicalSupplement = retrievalHealth.ok && insufficientForFive;
  const supplementReasons = [];
  if (!retrievalHealth.ok) {
    supplementReasons.push("检索链存在技术错误，禁止把技术空结果送入研究补检或判为医学证据不足");
  }
  if (hardCandidateCount < 2) {
    supplementReasons.push("硬证据候选少于2条");
  }
  if (estimatedQuestionCapacity < 5) {
    supplementReasons.push("压缩证据池的理论五题容量不足");
  }

  const keptCounts = Object.fromEntries(
    Object.entries(laneEvidenceIds).map(([lane, ids]) => [lane, ids.length])
  );
  const compressionReport = {
    input_counts: inputCounts,
    kept_counts: keptCounts,
    kept_total: records.length,
    dropped_total: dropped.length,
    dropped
  };
  const capacityReport = {
    hard_candidate_count: hardCandidateCount,
    eligible_candidate_count: eligibleCandidateCount,
    decision_domain_count: decisionDomains.length,
    decision_domains: decisionDomains,
    estimated_question_capacity: estimatedQuestionCapacity,
    evidence_pool_insufficient_for_five: insufficientForFive,
    identifiable_initial_study_count: initialStudyCount,
    identifiable_supplement_study_count: supplementStudyCount
  };
  const evidencePool = {
    contract_version: "1.2",
    publication_schema_version: "1.1",
    limits: LANE_LIMITS,
    records,
    lanes: laneEvidenceIds,
    retrieval_health: retrievalHealth,
    capacity_report: capacityReport,
    compression_report: compressionReport
  };

  return {
    evidence_pool: evidencePool,
    evidence_pool_json: JSON.stringify(evidencePool),
    retrieval_health_ok: retrievalHealth.ok,
    retrieval_health: retrievalHealth,
    retrieval_errors: retrievalErrors,
    needs_clinical_supplement: needsClinicalSupplement,
    supplement_decision: !retrievalHealth.ok
      ? "BLOCKED_TECHNICAL"
      : insufficientForFive
        ? "TRIGGER"
        : "SKIP",
    supplement_reason: supplementReasons.join("；"),
    evidence_pool_insufficient_for_five: insufficientForFive,
    estimated_question_capacity: estimatedQuestionCapacity,
    hard_candidate_count: hardCandidateCount,
    eligible_candidate_count: eligibleCandidateCount,
    identifiable_initial_study_count: initialStudyCount,
    identifiable_supplement_study_count: supplementStudyCount,
    compression_report: compressionReport,
    compression_report_json: JSON.stringify(compressionReport)
  };
}

function main({
  adverse_events,
  fallback_anchor_a,
  fallback_anchor_b
}) {
  const EVENT_PATTERNS = [
    { pattern: /1型糖尿病|type\s*1\s*diabetes|T1DM/i, label: "1型糖尿病" },
    { pattern: /糖尿病酮症酸中毒|\bDKA\b/i, label: "糖尿病酮症酸中毒" },
    { pattern: /间质性肺炎|免疫相关肺炎|肺炎|pneumonitis|interstitial\s+lung/i, label: "肺炎/间质性肺病" },
    { pattern: /心肌炎|myocarditis/i, label: "心肌炎" },
    { pattern: /肝炎|免疫相关肝损伤|hepatitis/i, label: "肝炎/肝损伤" },
    { pattern: /结肠炎|colitis/i, label: "结肠炎" },
    { pattern: /垂体炎|hypophysitis/i, label: "垂体炎" },
    { pattern: /甲状腺炎|甲状腺功能|thyroid/i, label: "甲状腺功能异常" },
    { pattern: /肾上腺功能|adrenal/i, label: "肾上腺功能异常" },
    { pattern: /肾炎|免疫相关肾损伤|nephritis/i, label: "肾炎/肾损伤" },
