    return -1;
  }

  function findRootArray(text, propertyName) {
    let objectDepth = 0;
    let arrayDepth = 0;
    for (let index = 0; index < text.length; index++) {
      const char = text[index];
      if (char === '"') {
        const end = readStringEnd(text, index);
        if (end < 0) return null;
        if (objectDepth === 1 && arrayDepth === 0) {
          let key = "";
          try {
            key = JSON.parse(text.slice(index, end));
          } catch (_) {
            return null;
          }
          if (key === propertyName) {
            let cursor = skipWhitespace(text, end);
            if (text[cursor] === ":") {
              cursor = skipWhitespace(text, cursor + 1);
              if (text[cursor] === "[") {
                const arrayEnd = scanValueEnd(text, cursor);
                return arrayEnd > cursor
                  ? { start: cursor, end: arrayEnd }
                  : null;
              }
            }
          }
        }
        index = end - 1;
        continue;
      }
      if (char === "{") objectDepth += 1;
      else if (char === "}") objectDepth -= 1;
      else if (char === "[") arrayDepth += 1;
      else if (char === "]") arrayDepth -= 1;
    }
    return null;
  }

  function extractArrayElements(text, propertyName) {
    const span = findRootArray(text, propertyName);
    if (!span) return { span: null, elements: [] };
    const elements = [];
    let cursor = span.start + 1;
    while (cursor < span.end - 1) {
      cursor = skipWhitespace(text, cursor);
      if (text[cursor] === ",") {
        cursor += 1;
        continue;
      }
      if (cursor >= span.end - 1 || text[cursor] === "]") break;
      const end = scanValueEnd(text, cursor);
      if (end <= cursor) return { span, elements: [], invalid: true };
      const raw = text.slice(cursor, end);
      try {
        elements.push({ start: cursor, end, raw, value: JSON.parse(raw) });
      } catch (_) {
        return { span, elements: [], invalid: true };
      }
      cursor = end;
    }
    return { span, elements, invalid: false };
  }

  function normalizeTasks(packet) {
    if (!hasOwn(packet, "repair_tasks") || !Array.isArray(packet.repair_tasks)) {
      errors.push("repair_packet.repair_tasks必须为数组，且不得从旧字段或字符串回退");
      return [];
    }

    const tasks = [];
    const seen = new Set();
    for (const task of packet.repair_tasks) {
      if (!task || typeof task !== "object" || Array.isArray(task)) {
        errors.push("repair_tasks中的每一项都必须是对象");
        continue;
      }
      const keys = Object.keys(task).sort();
      const expectedKeys = [...REPAIR_TASK_KEYS].sort();
      if (!semanticEqual(keys, expectedKeys)) {
        errors.push(
          `repair_task只能含target_ids、code、fields、message四字段：${JSON.stringify(
            task
          )}`
        );
        continue;
      }
      if (
        !Array.isArray(task.target_ids) ||
        task.target_ids.some((id) => typeof id !== "string" || !/^Q[1-5]$/.test(id)) ||
        new Set(task.target_ids).size !== task.target_ids.length
      ) {
        errors.push(`repair_task ${String(task.code || "")} 的target_ids无效`);
        continue;
      }
      if (!nonEmptyString(task.code) || !/^[A-Z][A-Z0-9_]*$/.test(task.code)) {
        errors.push("repair_task.code必须为非空大写英文错误码");
        continue;
      }
      if (
        !Array.isArray(task.fields) ||
        task.fields.length === 0 ||
        task.fields.some((field) => !nonEmptyString(field))
      ) {
        errors.push(`repair_task ${task.code} 的fields必须为非空字符串数组`);
        continue;
      }
      if (!nonEmptyString(task.message)) {
        errors.push(`repair_task ${task.code} 的message必须非空`);
        continue;
      }
      const normalized = {
        target_ids: [...task.target_ids],
        code: task.code,
        fields: [...task.fields],
        message: task.message
      };
      const key = canonical(normalized);
      if (seen.has(key)) continue;
      seen.add(key);
      tasks.push(normalized);
    }
    if (tasks.length === 0) {
      errors.push("repair_packet必须至少包含一项有效repair_task");
    }
    return tasks;
  }

  function changedForField(previous, replacement, field) {
    const evidenceBindingFields = [
      "guidelineRef",
      "evidence_type",
      "doc_id",
      "split_index",
      "authority",
      "source_title",
      "source_version",
      "source_section",
      "source_url"
    ];
    if (evidenceBindingFields.includes(field)) {
      if (
        (hasOwn(previous, field) || hasOwn(replacement, field)) &&
        !semanticEqual(previous[field], replacement[field])
      ) {
        return true;
      }
      return ["evidence_id", "support_mode", "evidence_summary"].some(
        (key) => !semanticEqual(previous[key], replacement[key])
      );
    }
    if (field === "all" || field === "questions") {
      return !semanticEqual(previous, replacement);
    }
    return !semanticEqual(previous[field], replacement[field]);
  }

  function rootOnlyTask(task) {
    return (
      Array.isArray(task.fields) &&
      task.fields.length > 0 &&
      task.fields.every((field) => ROOT_ONLY_FIELDS.has(field))
    );
  }

  function failure() {
    return {
      merged_internal_json: "",
      merge_decision: "FAIL",
      merge_errors: errors,
      changed_ids: [],
      preserved_ids: []
    };
  }

  const packetResult = parseObject(source.repair_packet, "repair_packet", false);
  const patchResult = parseObject(source.patch_json, "patch_json", false);
  const previousResult = parseObject(
    source.previous_internal_json,
    "previous_internal_json",
    true
  );
  if (!packetResult.valid || !patchResult.valid) return failure();

  const packet = packetResult.parsed;
  const patch = patchResult.parsed;
  const tasks = normalizeTasks(packet);
  const requestedMode = packet.revision_mode || "";
  if (!new Set(["PATCH", "FULL"]).has(requestedMode)) {
    errors.push("repair_packet.revision_mode必须明确为PATCH或FULL，不得由模型patch_json自行选择");
  }
  if (!new Set(["PATCH", "FULL"]).has(patch.revision_mode)) {
    errors.push("patch_json.revision_mode只能为PATCH或FULL");
  } else if (requestedMode && patch.revision_mode !== requestedMode) {
    errors.push(
      `patch_json.revision_mode=${patch.revision_mode}与授权模式${requestedMode}不一致`
    );
  }
  const allowedPatchRootKeys = new Set([
    "revision_mode",
    "replacements",
    "generation_status",
    "missing_information",
    "risk_message",
    ...(requestedMode === "FULL" ? ["case_summary"] : [])
  ]);
  const unexpectedPatchRootKeys = Object.keys(patch).filter(
    (key) => !allowedPatchRootKeys.has(key)
  );
  if (unexpectedPatchRootKeys.length > 0) {
    errors.push(`patch_json包含未授权根字段：${unexpectedPatchRootKeys.join("、")}`);
  }
  if (requestedMode === "PATCH" && hasOwn(patch, "case_summary")) {
    errors.push("PATCH不得输出case_summary；该字段必须逐字保留上一轮值");
  }
  if (!new Set(["success", "insufficient"]).has(patch.generation_status)) {
    errors.push("patch_json.generation_status只能为success或insufficient");
  }
  if (
    requestedMode === "FULL" &&
    (!nonEmptyString(patch.case_summary) || patch.case_summary.length > 400)
  ) {
    errors.push("FULL修订必须返回非空且不超过400字的case_summary");
  }

  if (patch.generation_status === "insufficient") {
    if (!Array.isArray(patch.replacements) || patch.replacements.length !== 0) {
      errors.push("修订结果insufficient时replacements必须为空数组");
    }
    if (
      !Array.isArray(patch.missing_information) ||
      patch.missing_information.length === 0 ||
      patch.missing_information.some((item) => !nonEmptyString(item))
    ) {
      errors.push("修订结果insufficient时missing_information必须具体且非空");
    }
    if (!nonEmptyString(patch.risk_message)) {
      errors.push("修订结果insufficient时risk_message必须具体且非空");
    }
    if (errors.length > 0) return failure();
    const previous = previousResult.valid ? previousResult.parsed : {};
    const insufficient = {
      schema_version: "1.1",
      generation_status: "insufficient",
      case_summary:
        requestedMode === "FULL"
          ? patch.case_summary
          : typeof previous.case_summary === "string"
            ? previous.case_summary
            : typeof patch.case_summary === "string"
              ? patch.case_summary
              : "",
      question_count: 0,
      difficulty: "进阶",
      questions: [],
      missing_information: patch.missing_information,
      risk_message: patch.risk_message
    };
    return {
      merged_internal_json: JSON.stringify(insufficient),
      merge_decision: "INSUFFICIENT",
      merge_errors: [],
      changed_ids: [],
      preserved_ids: []
    };
  }

  if (!Array.isArray(patch.replacements)) {
    errors.push("patch_json.replacements必须为数组");
  }
  if (!Array.isArray(patch.missing_information) || patch.missing_information.length !== 0) {
    errors.push("修订结果success时missing_information必须为空数组");
  }
  if (patch.risk_message !== "") {
    errors.push("修订结果success时risk_message必须为空字符串");
  }
  if (errors.length > 0) return failure();

  const replacements = patch.replacements;
  const replacementById = new Map();
  for (const replacement of replacements) {
    if (!replacement || typeof replacement !== "object" || Array.isArray(replacement)) {
      errors.push("每个replacement必须是完整内部题对象");
      continue;
    }
    if (!nonEmptyString(replacement.id) || !/^Q[1-5]$/.test(replacement.id)) {
      errors.push("replacement.id只能为Q1至Q5");
      continue;
    }
    if (replacementById.has(replacement.id)) {
      errors.push(`patch_json重复提供${replacement.id}`);
      continue;
    }
    replacementById.set(replacement.id, replacement);
  }
  if (errors.length > 0) return failure();

  const questionAuthorizedIds = new Set(
    tasks
      .filter((task) => !rootOnlyTask(task))
      .flatMap((task) => task.target_ids)
  );
  const patchIds = new Set(replacementById.keys());
  const previousQuestions =
    previousResult.valid && Array.isArray(previousResult.parsed.questions)
      ? previousResult.parsed.questions
      : [];
  const previousById = new Map();
  for (const question of previousQuestions) {
    if (!question || typeof question !== "object" || Array.isArray(question)) continue;
    if (nonEmptyString(question.id)) {
      if (previousById.has(question.id)) {
        errors.push(`previous_internal_json中题号${question.id}重复`);
      } else {
        previousById.set(question.id, question);
      }
    }
  }

  if (requestedMode === "PATCH") {
    if (!previousResult.valid || !Array.isArray(previousResult.parsed.questions)) {
      errors.push("PATCH要求previous_internal_json为含questions数组的可解析对象");
    }
    if (tasks.some(rootOnlyTask)) {
      errors.push("根字段修复任务必须使用FULL，不能使用PATCH");
    }
    if (tasks.length === 0 || questionAuthorizedIds.size === 0) {
      errors.push("PATCH必须包含至少一个有target_ids的repair_task");
    }
    for (const id of questionAuthorizedIds) {
      if (!patchIds.has(id)) errors.push(`PATCH漏修授权目标题${id}`);
      if (!previousById.has(id)) errors.push(`PATCH授权题${id}不在上一轮题集中`);
    }
    for (const id of patchIds) {
      if (!questionAuthorizedIds.has(id)) errors.push(`PATCH越权修改或新增题号${id}`);
    }
    if (hasOwn(patch, "questions")) {
      errors.push("PATCH只能通过replacements返回授权题，不得返回完整questions字段");
    }
  } else if (requestedMode === "FULL") {
    if (
      replacements.length !== 5 ||
      EXPECTED_IDS.some((id) => !patchIds.has(id)) ||
      patchIds.size !== 5
    ) {
      errors.push("FULL的replacements必须恰好包含Q1至Q5各一次");
    }
  }
  if (errors.length > 0) return failure();

  for (const task of tasks) {
    if (rootOnlyTask(task)) continue;
    const comparableTargets = task.target_ids.filter(
      (id) => previousById.has(id) && replacementById.has(id)
    );
    for (const id of task.target_ids) {
      if (!replacementById.has(id)) {
        errors.push(`repair_task ${task.code} 的目标题${id}没有replacement`);
      }
    }
    if (requestedMode === "PATCH") {
      for (const id of comparableTargets) {
        const previous = previousById.get(id);
        const replacement = replacementById.get(id);
        if (!task.fields.some((field) => changedForField(previous, replacement, field))) {
          errors.push(
            `${id}只修改了与repair_task ${task.code}无关的字段，任务字段均未发生实质变化`
          );
        }
      }
    } else if (
      comparableTargets.length > 0 &&
      !comparableTargets.some((id) =>
        task.fields.some((field) =>
          changedForField(previousById.get(id), replacementById.get(id), field)
        )
      )
    ) {
      errors.push(
        `FULL未对repair_task ${task.code}的任何授权目标题完成相关实质变化`
      );
    }
  }

  if (requestedMode === "PATCH") {
    for (const id of questionAuthorizedIds) {
      const previous = previousById.get(id);
      if (previous && semanticEqual(previous, replacementById.get(id))) {
        errors.push(`${id}与上一轮完全相同，未完成实质修订`);
      }
    }
  }
  if (errors.length > 0) return failure();

  if (requestedMode === "FULL") {
    const previous = previousResult.valid ? previousResult.parsed : {};
    const explicitPreserveIds = Array.isArray(packet.preserve_ids)
      ? packet.preserve_ids
      : [];
    if (
      explicitPreserveIds.some((id) => !/^Q[1-5]$/.test(String(id))) ||
      new Set(explicitPreserveIds).size !== explicitPreserveIds.length
    ) {
      errors.push("repair_packet.preserve_ids必须是互异的Q1至Q5数组");
      return failure();
    }
    if (previousResult.valid && previousQuestions.length > 0) {
      const mustPreserve = EXPECTED_IDS.filter(
        (id) => previousById.has(id) && !questionAuthorizedIds.has(id)
      );
      if (explicitPreserveIds.length > 0) {
        const declared = [...explicitPreserveIds].sort();
        const expected = [...mustPreserve].sort();
        if (!semanticEqual(declared, expected)) {
          errors.push("FULL的preserve_ids必须恰好列出所有未被repair_tasks.target_ids授权的题号");
        }
      }
      for (const id of mustPreserve) {
        if (
          previousById.has(id) &&
          !semanticEqual(previousById.get(id), replacementById.get(id))
        ) {
          errors.push(`FULL越权修改未列入target_ids的题${id}`);
        }
      }
      if (errors.length > 0) return failure();
    }
    const merged = {
      ...previous,
      schema_version: "1.1",
      generation_status: "success",
      case_summary: patch.case_summary,
      question_count: 5,
      difficulty: "进阶",
      questions: EXPECTED_IDS.map((id) => replacementById.get(id)),
      missing_information: [],
      risk_message: ""
    };
    if (previousResult.valid) {
      for (const task of tasks.filter(rootOnlyTask)) {
        if (
          !task.fields.some((field) =>
            !semanticEqual(previous[field], merged[field])
          )
        ) {
          errors.push(`FULL未修复根字段任务${task.code}`);
        }
      }
      if (errors.length > 0) return failure();
    }
    const changedIds = EXPECTED_IDS.filter(
      (id) => !previousById.has(id) || !semanticEqual(previousById.get(id), replacementById.get(id))
    );
    if (previousResult.valid && semanticEqual(previous, merged)) {
      errors.push("第二轮FULL结果与上一轮候选完全相同");
      return failure();
    }
    let mergedRaw = JSON.stringify(merged);
    if (previousResult.valid && previousQuestions.length > 0) {
      const previousElements = extractArrayElements(
        previousResult.raw,
        "questions"
      );
      if (
        !previousElements.span ||
        previousElements.invalid ||
        previousElements.elements.length !== previousQuestions.length
      ) {
        errors.push("FULL无法定位上一轮questions原始字节区间");
        return failure();
      }
      const previousRawById = new Map();
      for (const element of previousElements.elements) {
        const id =
          element.value && typeof element.value === "object"
            ? element.value.id
            : "";
        if (nonEmptyString(id)) previousRawById.set(id, element.raw);
      }
      const patchElements = extractArrayElements(patchResult.raw, "replacements");
      const patchRawById = new Map();
      if (patchElements.span && !patchElements.invalid) {
        for (const element of patchElements.elements) {
          const id =
            element.value && typeof element.value === "object"
              ? element.value.id
              : "";
          if (nonEmptyString(id)) patchRawById.set(id, element.raw);
        }
      }
      const mergedQuestionRaws = EXPECTED_IDS.map((id) => {
        const previousQuestion = previousById.get(id);
        const replacement = replacementById.get(id);
        if (
          previousQuestion &&
          semanticEqual(previousQuestion, replacement) &&
          previousRawById.has(id)
        ) {
          return previousRawById.get(id);
        }
        return patchRawById.get(id) || JSON.stringify(replacement);
      });
      const skeletonArray = findRootArray(mergedRaw, "questions");
      if (!skeletonArray) {
        errors.push("FULL无法构造合并后的questions数组");
        return failure();
      }
      mergedRaw =
        mergedRaw.slice(0, skeletonArray.start) +
        `[${mergedQuestionRaws.join(",")}]` +
        mergedRaw.slice(skeletonArray.end);
      try {
        JSON.parse(mergedRaw);
      } catch (error) {
        errors.push(
          `FULL合并后JSON不可解析：${String(
            error && error.message ? error.message : error
          )}`
        );
        return failure();
      }
    }
    return {
      merged_internal_json: mergedRaw,
      merge_decision: "PASS",
      merge_errors: [],
      changed_ids: changedIds,
      preserved_ids: EXPECTED_IDS.filter((id) => !changedIds.includes(id))
    };
  }

  const previousElements = extractArrayElements(previousResult.raw, "questions");
  const patchElements = extractArrayElements(patchResult.raw, "replacements");
  if (
    !previousElements.span ||
    previousElements.invalid ||
    previousElements.elements.length !== previousQuestions.length
  ) {
    errors.push("无法从previous_internal_json精确定位questions原始字节区间");
    return failure();
  }
  const rawReplacementById = new Map();
  if (patchElements.span && !patchElements.invalid) {
    for (const element of patchElements.elements) {
      if (
        element.value &&
        typeof element.value === "object" &&
        nonEmptyString(element.value.id)
      ) {
        rawReplacementById.set(element.value.id, element.raw);
      }
    }
  }

  const edits = [];
  const previousRawById = new Map();
  for (const element of previousElements.elements) {
    const id =
      element.value && typeof element.value === "object" ? element.value.id : "";
    if (nonEmptyString(id)) previousRawById.set(id, element.raw);
    if (!questionAuthorizedIds.has(id)) continue;
    edits.push({
      start: element.start,
      end: element.end,
      raw:
        rawReplacementById.get(id) || JSON.stringify(replacementById.get(id))
    });
  }
  if (edits.length !== questionAuthorizedIds.size) {
    errors.push("PATCH未能为每个授权题定位唯一原始字节区间");
    return failure();
  }

  let mergedRaw = previousResult.raw;
  for (const edit of edits.sort((left, right) => right.start - left.start)) {
    mergedRaw = mergedRaw.slice(0, edit.start) + edit.raw + mergedRaw.slice(edit.end);
  }
  let mergedParsed;
  try {
    mergedParsed = JSON.parse(mergedRaw);
  } catch (error) {
    errors.push(
      `PATCH合并后JSON不可解析：${String(
        error && error.message ? error.message : error
      )}`
    );
    return failure();
  }

  if (!Array.isArray(mergedParsed.questions) || mergedParsed.questions.length !== previousQuestions.length) {
    errors.push("PATCH合并后题目数量发生变化");
    return failure();
  }
  const mergedIds = mergedParsed.questions.map((question) =>
    question && typeof question === "object" ? question.id : ""
  );
  const previousIds = previousQuestions.map((question) =>
    question && typeof question === "object" ? question.id : ""
  );
  if (!semanticEqual(mergedIds, previousIds)) {
    errors.push("PATCH合并后题号或顺序发生变化");
    return failure();
  }
  const mergedById = new Map(
    mergedParsed.questions.map((question) => [
      question && typeof question === "object" ? question.id : "",
      question
    ])
  );
  for (const id of questionAuthorizedIds) {
    if (!semanticEqual(mergedById.get(id), replacementById.get(id))) {
      errors.push(`PATCH合并后授权题${id}的解析值与replacement不一致`);
    }
  }
  if (errors.length > 0) return failure();

  const mergedElements = extractArrayElements(mergedRaw, "questions");
  const mergedRawById = new Map();
  for (const element of mergedElements.elements) {
    const id =
      element.value && typeof element.value === "object" ? element.value.id : "";
    if (nonEmptyString(id)) mergedRawById.set(id, element.raw);
  }
  const preservedIds = previousIds.filter(
    (id) => nonEmptyString(id) && !questionAuthorizedIds.has(id)
  );
  for (const id of preservedIds) {
    if (previousRawById.get(id) !== mergedRawById.get(id)) {
      errors.push(`PATCH未逐字节保留未授权题${id}`);
    }
  }

  const explicitPreserveIds = Array.isArray(packet.preserve_ids)
    ? packet.preserve_ids
    : null;
  if (explicitPreserveIds) {
    const invalidFormat = explicitPreserveIds.some(
      (id) => typeof id !== "string" || !/^Q[1-5]$/.test(id)
    );
    const hasDuplicates =
      new Set(explicitPreserveIds).size !== explicitPreserveIds.length;
    const declared = [...explicitPreserveIds].sort();
    const actual = [...preservedIds].sort();
    if (invalidFormat || hasDuplicates || !semanticEqual(declared, actual)) {
      errors.push("repair_packet.preserve_ids与实际未授权题集合不一致");
    }
  }
  if (errors.length > 0) return failure();

  return {
    merged_internal_json: mergedRaw,
    merge_decision: "PASS",
    merge_errors: [],
    changed_ids: previousIds.filter((id) => questionAuthorizedIds.has(id)),
    preserved_ids: preservedIds
  };
}

// Text-shape signals only. Never change options or infer medical correctness.
function optionStyleMetrics(question) {
  const q = question && typeof question === 'object' ? question : {};
  const letters = ['A', 'B', 'C', 'D'];
  const options = Array.isArray(q.options) ? q.options : letters.map(k => q.options && q.options[k]);
  const answer = typeof q.answer === 'number' ? q.answer : letters.indexOf(String(q.answer || '').toUpperCase());
  if (options.length !== 4 || options.some(s => typeof s !== 'string' || !s.trim()) || !Number.isInteger(answer) || answer < 0 || answer > 3) return null;
  // Count Unicode characters except spaces/punctuation/symbols; letters/digits count individually.
  const lengths = options.map(s => Array.from(s.replace(/[\s\p{P}\p{S}]/gu, '')).length);
  const wrongLengths = lengths.filter((_, i) => i !== answer).sort((a, b) => a - b);
  const medianWrong = wrongLengths[1];
  const longest = Math.max(...lengths), shortest = Math.min(...lengths);
  const uniqueLongest = lengths[answer] === longest && lengths.filter(n => n === longest).length === 1;
  const codes = [];
  if (uniqueLongest && lengths[answer] - medianWrong >= 6 && lengths[answer] > medianWrong * 1.4) codes.push('CORRECT_OPTION_LONGER');
  if (longest - shortest >= 8 && longest > shortest * 1.5) codes.push('OPTION_LENGTH_SPREAD');
  // These phrases are review clues, not proof that the corresponding option is wrong.
  const absolutePattern = /所有.{0,12}(?:均|都)|(?:一定|必然|必为|必定|绝不|完全可靠)|不会(?:发生|复发)|无需(?:任何|所有)|停止所有|放弃所有|等待自然病程/;
  const absolutePositions = options.map((s, i) => absolutePattern.test(s) ? letters[i] : null).filter(Boolean);
  if (absolutePositions.length && !absolutePositions.includes(letters[answer])) codes.push('DISTRACTOR_ABSOLUTE_CUE');
  const warnings = [];
  if (codes.includes('CORRECT_OPTION_LONGER')) warnings.push('正确项独自较长：应复核是否只有正确项包含条件、理由或多个动作。');
  if (codes.includes('OPTION_LENGTH_SPREAD')) warnings.push('四项长度差异较大：应统一表达层次，不得机械补字或截断。');
  if (codes.includes('DISTRACTOR_ABSOLUTE_CUE')) warnings.push('干扰项含绝对化或极端措辞：需复核是否构成无需医学推理的排除线索，不能仅凭关键词判错。');
  return {
    version: 'option-style-1.0', length_unit: 'unicode_chars_excluding_spaces_punctuation_symbols',
    option_lengths: lengths, answer_position: letters[answer], correct_is_unique_longest: uniqueLongest,
    correct_to_distractor_median_ratio: medianWrong ? Number((lengths[answer] / medianWrong).toFixed(2)) : null,
    max_min_difference: longest - shortest,
    max_min_ratio: shortest ? Number((longest / shortest).toFixed(2)) : null,
    absolute_phrase_positions: absolutePositions, warning_codes: codes, warnings,
    interpretation: '仅为措辞线索，不是医学质量评分；无提示也不等于无缺陷。药名、缩写或必要条件可能导致合理长度差异。'
  };
}

function main(inputs) {
  const source = inputs && typeof inputs === "object" ? inputs : {};
  const ROOT_FIELDS = [
    "schema_version",
    "generation_status",
    "case_summary",
    "question_count",
    "difficulty",
    "questions",
    "missing_information",
    "risk_message"
  ];
  const INTERNAL_QUESTION_FIELDS = [
    "id",
    "type",
    "phase",
    "timepoint",
    "question",
    "options",
    "answer",
    "answer_text",
    "explain",
    "keyPoint",
    "evidence_id",
    "support_mode",
    "evidence_summary"
  ];
  const PUBLIC_QUESTION_FIELDS = [
    "id",
    "type",
    "phase",
    "timepoint",
    "question",
    "options",
    "answer",
    "answer_text",
    "explain",
    "keyPoint"
  ];
  const REF_FIELDS = [
    "evidence_type",
    "doc_id",
    "split_index",
    "type",
    "authority",
    "source_title",
    "source_version",
    "source_section",
    "source_url",
    "evidence_summary"
  ];
  const ABILITY_TYPES = new Set([
    "诊断与分期",
    "分子诊断",
    "治疗决策",
    "疗效复评与局部治疗",
    "耐药与后线管理",
    "不良反应管理"
  ]);
  const SUPPORT_MODES = new Set(["hard", "clinical_reasoning"]);
  const FORBIDDEN_MODEL_METADATA = [
    "guidelineRef",
    "evidence_type",
    "doc_id",
    "split_index",
    "authority",
    "source_title",
    "source_version",
    "source_section",
    "source_url"
  ];
  const FULL_INTERNAL_FIELDS = INTERNAL_QUESTION_FIELDS.filter(
    (field) => field !== "id"
  );
  const errors = [];
  const warnings = [];
  const repairTasks = [];
  const repairTaskKeys = new Set();
  let requiresFullRevision = false;

  function hasOwn(object, key) {
    return Boolean(object && Object.prototype.hasOwnProperty.call(object, key));
  }

  function nonEmptyString(value) {
    return typeof value === "string" && Boolean(value.trim());
  }

  function normalizedText(value) {
    return typeof value === "string" ? value.replace(/\s+/g, " ").trim() : "";
  }

  function pushTask(task) {
    if (task.scope === "root" || task.scope === "set") {
      requiresFullRevision = true;
    }
    const normalized = {
      target_ids: Array.from(
        new Set(
          (Array.isArray(task.target_ids) ? task.target_ids : []).filter(
            (id) => typeof id === "string" && /^Q[1-5]$/.test(id)
          )
        )
      ),
      code: nonEmptyString(task.code) ? task.code : "STRUCTURE_ERROR",
      fields: Array.from(
        new Set(
          (Array.isArray(task.fields) ? task.fields : []).filter(
            (field) => typeof field === "string" && field
          )
        )
      ),
      message: nonEmptyString(task.message) ? task.message : "修复机械结构错误"
    };
    const key = JSON.stringify(normalized);
    if (repairTaskKeys.has(key)) return;
    repairTaskKeys.add(key);
    repairTasks.push(normalized);
  }

  function fail(message, task) {
    errors.push(message);
    if (task) pushTask(task);
  }

  function questionTask(id, code, fields, message) {
    return {
      scope: "question",
      target_ids: /^Q[1-5]$/.test(String(id)) ? [String(id)] : [],
      code,
      fields,
      message
    };
  }

  function setTask(code, targetIds, message) {
    return {
      scope: "set",
      target_ids: targetIds,
      code,
      fields: FULL_INTERNAL_FIELDS,
      message
    };
  }

  function rootTask(code, fields, message) {
    return {
      scope: "root",
      target_ids: [],
      code,
      fields,
      message
    };
  }

  function readJsonStringEnd(text, start) {
    let escaped = false;
    for (let index = start + 1; index < text.length; index++) {
      const char = text[index];
      if (escaped) escaped = false;
      else if (char === "\\") escaped = true;
      else if (char === '"') return index + 1;
    }
    return -1;
  }

  function skipJsonWhitespace(text, start) {
    let cursor = start;
    while (cursor < text.length && /\s/.test(text[cursor])) cursor += 1;
    return cursor;
  }

  function scanJsonValueEnd(text, start) {
    const first = text[start];
    if (first === '"') return readJsonStringEnd(text, start);
    if (first !== "{" && first !== "[") {
      let cursor = start;
      while (
        cursor < text.length &&
        text[cursor] !== "," &&
        text[cursor] !== "}" &&
        text[cursor] !== "]"
      ) {
        cursor += 1;
      }
      return cursor;
    }

    let objectDepth = 0;
    let arrayDepth = 0;
    let inString = false;
    let escaped = false;
    for (let index = start; index < text.length; index++) {
      const char = text[index];
      if (inString) {
        if (escaped) escaped = false;
        else if (char === "\\") escaped = true;
        else if (char === '"') inString = false;
        continue;
      }
      if (char === '"') {
        inString = true;
        continue;
      }
      if (char === "{") objectDepth += 1;
      else if (char === "}") objectDepth -= 1;
      else if (char === "[") arrayDepth += 1;
      else if (char === "]") arrayDepth -= 1;
      if (objectDepth === 0 && arrayDepth === 0) return index + 1;
    }
    return -1;
  }

  function duplicateRootKeys(text) {
    let cursor = skipJsonWhitespace(text, 0);
    if (text[cursor] !== "{") return [];
    cursor += 1;
    const seen = new Set();
    const duplicates = new Set();

    while (cursor < text.length) {
      cursor = skipJsonWhitespace(text, cursor);
      if (text[cursor] === "}") break;
      if (text[cursor] !== '"') return [];
      const keyEnd = readJsonStringEnd(text, cursor);
      if (keyEnd < 0) return [];
      let key;
      try {
        key = JSON.parse(text.slice(cursor, keyEnd));
      } catch (_) {
        return [];
      }
      if (seen.has(key)) duplicates.add(key);
      seen.add(key);
      cursor = skipJsonWhitespace(text, keyEnd);
      if (text[cursor] !== ":") return [];
      cursor = skipJsonWhitespace(text, cursor + 1);
      const valueEnd = scanJsonValueEnd(text, cursor);
      if (valueEnd <= cursor) return [];
      cursor = skipJsonWhitespace(text, valueEnd);
      if (text[cursor] === ",") {
        cursor += 1;
        continue;
      }
      if (text[cursor] === "}") break;
      return [];
    }
    return Array.from(duplicates).sort();
  }

  function parseCandidate(value) {
    if (value && typeof value === "object" && !Array.isArray(value)) {
      return { parsed: value, raw: JSON.stringify(value), error: "" };
    }
    if (typeof value !== "string" || !value.trim()) {
      return { parsed: null, raw: "", error: "候选为空或不是JSON对象/字符串" };
    }
    try {
      const parsed = JSON.parse(value);
      if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
        return {
          parsed: null,
          raw: value,
          error: "候选根值必须是JSON对象"
        };
      }
      const duplicates = duplicateRootKeys(value);
      if (duplicates.length > 0) {
        return {
          parsed: null,
          raw: value,
          error: `候选根对象存在重复键：${duplicates.join("、")}`
        };
      }
      return { parsed, raw: value, error: "" };
    } catch (error) {
      return {
        parsed: null,
        raw: value,
        error: `候选不能被JSON.parse直接解析：${String(
          error && error.message ? error.message : error
        )}`
      };
    }
  }

  function parsePool(value) {
    if (typeof value === "string") {
      if (!value.trim()) return { pool: {}, error: "evidence_pool为空" };
      try {
        const parsed = JSON.parse(value);
        return {
          pool: parsed && typeof parsed === "object" ? parsed : {},
          error:
            parsed && typeof parsed === "object"
              ? ""
              : "evidence_pool根值不是对象或数组"
        };
      } catch (error) {
        return {
          pool: {},
          error: `evidence_pool不能被JSON.parse直接解析：${String(
            error && error.message ? error.message : error
          )}`
        };
      }
    }
    if (value && typeof value === "object") return { pool: value, error: "" };
    return { pool: {}, error: "evidence_pool为空或不是对象" };
  }

  function poolRecords(pool) {
    if (Array.isArray(pool)) return pool;
    if (Array.isArray(pool.records)) return pool.records;
    const records = [];
    for (const lane of [
      "guideline_a",
      "guideline_b",
      "clinical_study_initial",
      "clinical_study_supplement",
      "irae_a",
      "irae_b"
    ]) {
      if (!Array.isArray(pool[lane])) continue;
      records.push(
        ...pool[lane].filter(
          (record) => record && typeof record === "object" && !Array.isArray(record)
        )
      );
    }
    return records;
  }

  function locatorKey(docId, splitIndex) {
    return `${String(docId)}::${String(splitIndex)}`;
  }

  function recordHardType(record) {
    if (["指南", "临床研究"].includes(record.hard_evidence_type)) {
      return record.hard_evidence_type;
    }
    const type = String(record.type || "").toLowerCase();
    if (type === "guideline" && nonEmptyString(record.authority)) return "指南";
    if (
      (record.lane === "clinical_study_initial" ||
        record.lane === "clinical_study_supplement") &&
      record.eligible_clinical_study === true
    ) {
      return "临床研究";
    }
    return "";
  }

  function recordReasoningEligible(record) {
    return record.reasoning_eligible === true || Boolean(recordHardType(record));
  }

  function forbiddenAnswerLetter(text) {
    const value = String(text === null || text === undefined ? "" : text);
    return (
      /正确答案(?:为|是|：|:)?\s*[ABCD](?![A-Za-z])/i.test(value) ||
      /选项\s*[ABCD](?![A-Za-z])/i.test(value) ||
      /[ABCD]\s*项(?![A-Za-z])/i.test(value)
    );
  }

  function hasAuditableQuestion(questions) {
    if (!Array.isArray(questions)) return false;
    return questions.some((question) => {
      if (!question || typeof question !== "object" || Array.isArray(question)) {
        return false;
      }
      if (nonEmptyString(question.question)) return true;
      if (Array.isArray(question.options) && question.options.some(nonEmptyString)) {
        return true;
      }
      return ["answer_text", "explain", "keyPoint", "timepoint"].some((field) =>
        nonEmptyString(question[field])
      );
    });
  }

  function blankReference(summary) {
    return {
      evidence_type: "",
      doc_id: "",
      split_index: "",
      type: "",
      authority: "",
      source_title: "",
      source_version: "",
      source_section: "",
      source_url: "",
      evidence_summary: typeof summary === "string" ? summary : ""
    };
  }

  function hydrateQuestion(question, record, evidenceType) {
    if (!question || typeof question !== "object" || Array.isArray(question)) {
      return question;
    }
    const hydrated = {};
    for (const field of PUBLIC_QUESTION_FIELDS) {
      if (hasOwn(question, field)) hydrated[field] = question[field];
    }
    const reference = blankReference(question.evidence_summary);
    if (record) {
      reference.evidence_type = evidenceType;
      reference.doc_id = hasOwn(record, "doc_id") ? record.doc_id : "";
      reference.split_index = hasOwn(record, "split_index")
        ? record.split_index
        : "";
      reference.type = typeof record.type === "string" ? record.type : "";
      reference.authority =
        typeof record.authority === "string" ? record.authority : "";
      reference.source_title =
        typeof record.source_title === "string" ? record.source_title : "";
      reference.source_version =
        typeof record.source_version === "string" ? record.source_version : "";
      reference.source_section =
        typeof record.source_section === "string" ? record.source_section : "";
      reference.source_url =
        typeof record.source_url === "string" ? record.source_url : "";
    }
    hydrated.guidelineRef = reference;
    return hydrated;
  }

  function validatorFullPool(pool, records) {
    const lanes =
      pool && pool.lanes && typeof pool.lanes === "object" && !Array.isArray(pool.lanes)
        ? pool.lanes
        : Object.fromEntries(
            [
              "guideline_a",
              "guideline_b",
              "clinical_study_initial",
              "clinical_study_supplement",
              "irae_a",
              "irae_b"
            ].map((lane) => [
              lane,
              records
                .filter((record) => record && record.lane === lane)
                .map((record) => record.evidence_id)
            ])
          );
    return {
      audit_mode: "FULL_POOL_FOR_INSUFFICIENCY",
      contract_version: pool.contract_version || "1.2",
      records,
      lanes,
      capacity_report:
        pool && pool.capacity_report && typeof pool.capacity_report === "object"
          ? pool.capacity_report
          : {},
      retrieval_health:
        pool && pool.retrieval_health && typeof pool.retrieval_health === "object"
          ? pool.retrieval_health
          : { ok: false, errors: [{ lane: "registry", message: "缺少检索健康状态" }] },
      compression_report:
        pool && pool.compression_report && typeof pool.compression_report === "object"
          ? pool.compression_report
          : {}
    };
  }

  function buildReturn({
    decision,
    medicalAuditable,
    publicCandidate,
    internalRaw,
    citedRecords,
    validatorEvidence,
    hardCount,
    reasoningCount
  }) {
    const publicRaw = publicCandidate ? JSON.stringify(publicCandidate) : "";
    const publicReferenceMap =
      publicCandidate && Array.isArray(publicCandidate.questions)
        ? publicCandidate.questions
            .filter((question) => question && typeof question === "object" && !Array.isArray(question))
            .map((question) => ({
              id: typeof question.id === "string" ? question.id : "",
              guidelineRef:
                question.guidelineRef && typeof question.guidelineRef === "object"
                  ? question.guidelineRef
                  : blankReference("")
            }))
        : [];
    const recommendedRevisionMode =
      errors.length === 0
        ? ""
        : requiresFullRevision
          ? "FULL"
          : "PATCH";
    return {
      structure_decision: decision,
      structure_errors: errors,
      structure_warnings: warnings,
      medical_auditable: medicalAuditable,
      candidate_json_passthrough: publicRaw,
      public_reference_map_json: JSON.stringify(publicReferenceMap),
      internal_candidate_json: internalRaw,
      cited_evidence: citedRecords,
      cited_evidence_json: JSON.stringify(citedRecords),
      validator_evidence_json: JSON.stringify(validatorEvidence),
      repair_tasks: repairTasks,
      repair_tasks_json: JSON.stringify(repairTasks),
      recommended_revision_mode: recommendedRevisionMode,
      hard_evidence_count: hardCount,
      clinical_reasoning_count: reasoningCount
    };
  }

  const candidateResult = parseCandidate(source.candidate_json);
  const poolResult = parsePool(source.evidence_pool);
  const records = poolRecords(poolResult.pool).filter(
    (record) => record && typeof record === "object" && !Array.isArray(record)
  );

  if (candidateResult.error) {
    fail(
      candidateResult.error,
      rootTask("JSON_PARSE", ROOT_FIELDS, "输出一个可被JSON.parse直接解析的完整内部候选对象")
    );
    return buildReturn({
      decision: "FAIL",
      medicalAuditable: false,
      publicCandidate: null,
      internalRaw: candidateResult.raw,
      citedRecords: [],
      validatorEvidence: [],
      hardCount: 0,
      reasoningCount: 0
    });
  }

  const candidate = candidateResult.parsed;
  const questions = Array.isArray(candidate.questions) ? candidate.questions : [];
  // Warning-only: the independent reviewer decides whether the wording leaks the answer.
  questions.forEach((q, index) => {
    const style = optionStyleMetrics(q);
    if (style && style.warnings.length) warnings.push(
      'OPTION_STYLE ' + (q.id || 'Q' + (index + 1)) +
      '：四项有效字符数=' + style.option_lengths.join('/') +
      '，正确项=' + style.answer_position + '；' + style.warnings.join(' ')
    );
  });
  const medicalAuditable =
    candidate.generation_status === "insufficient" || hasAuditableQuestion(questions);

  if (poolResult.error) {
    fail(
      poolResult.error,
      rootTask(
        "EVIDENCE_POOL_INVALID",
        ["evidence_pool"],
        "修复证据池输入后重新装配，禁止猜测来源元数据"
      )
    );
  } else {
    const health = poolResult.pool && poolResult.pool.retrieval_health;
    if (!health || typeof health !== "object" || typeof health.ok !== "boolean") {
      fail(
        "证据池缺少可核验的retrieval_health状态",
        rootTask("RETRIEVAL_HEALTH_MISSING", ["evidence_pool"], "修复检索错误接线与证据注册后重新执行")
      );
    } else if (health.ok !== true) {
      const messages = Array.isArray(health.errors)
        ? health.errors
            .map((item) => `${String(item && item.lane ? item.lane : "unknown")}: ${String(item && item.message ? item.message : "检索失败")}`)
            .join("；")
        : "检索节点返回错误";
      fail(
        `证据检索链存在技术错误：${messages}`,
        rootTask("RETRIEVAL_FAILURE", ["evidence_pool"], "修复检索工具错误后重新运行；不得把技术空结果判为医学证据不足")
      );
    }
  }

  for (const field of ROOT_FIELDS) {
    if (!hasOwn(candidate, field)) {
      fail(
        `根对象缺少字段：${field}`,
        rootTask("ROOT_FIELD_MISSING", [field], `补齐根字段${field}`)
      );
    }
  }
  if (candidate.schema_version !== "1.1") {
    fail(
      "schema_version必须逐字等于1.1",
      rootTask("SCHEMA_VERSION", ["schema_version"], "schema_version固定为1.1")
    );
  }
  if (candidate.difficulty !== "进阶") {
    fail(
      "difficulty必须逐字等于进阶",
      rootTask("DIFFICULTY", ["difficulty"], "difficulty固定为进阶")
    );
  }
  if (typeof candidate.case_summary !== "string") {
    fail(
      "case_summary必须为字符串",
      rootTask("CASE_SUMMARY_TYPE", ["case_summary"], "输出脱敏且忠实的病例摘要")
    );
  } else if (!candidate.case_summary.trim()) {
    fail(
      "case_summary必须为非空字符串",
      rootTask("CASE_SUMMARY_EMPTY", ["case_summary"], "输出非空、脱敏且忠实的病例摘要")
    );
  } else if (candidate.case_summary.length > 400) {
    fail(
      "case_summary超过400字",
      rootTask("CASE_SUMMARY_LENGTH", ["case_summary"], "在不改写病例事实的前提下将摘要限制在400字内")
    );
  }

  const publicCandidate = {};
  for (const field of ROOT_FIELDS) {
    if (field !== "questions" && hasOwn(candidate, field)) {
      publicCandidate[field] = candidate[field];
    }
  }

  if (candidate.generation_status === "insufficient") {
    if (candidate.question_count !== 0) {
      fail(
        "insufficient时question_count必须为0",
        rootTask("INSUFFICIENT_COUNT", ["question_count"], "insufficient时题量固定为0")
      );
    }
    if (!Array.isArray(candidate.questions) || candidate.questions.length !== 0) {
      fail(
        "insufficient时questions必须为空数组",
        rootTask("INSUFFICIENT_QUESTIONS", ["questions"], "insufficient时不得夹带候选题")
      );
    }
    if (
      !Array.isArray(candidate.missing_information) ||
      candidate.missing_information.length === 0 ||
      candidate.missing_information.some((item) => !nonEmptyString(item))
    ) {
      fail(
        "insufficient时missing_information必须为具体的非空字符串数组",
        rootTask(
          "INSUFFICIENT_MISSING_INFORMATION",
          ["missing_information"],
          "列明缺少的证据类型、适用人群或独立决策方向"
        )
      );
    }
    if (!nonEmptyString(candidate.risk_message)) {
      fail(
        "insufficient时risk_message必须具体且非空",
        rootTask("INSUFFICIENT_RISK", ["risk_message"], "具体说明为何不能安全形成固定五题")
      );
    }
    publicCandidate.questions = [];
    return buildReturn({
      decision: errors.length === 0 ? "INSUFFICIENT" : "FAIL",
      medicalAuditable,
      publicCandidate,
      internalRaw: candidateResult.raw,
      citedRecords: [],
      validatorEvidence: validatorFullPool(poolResult.pool, records),
      hardCount: 0,
      reasoningCount: 0
    });
  }

  if (candidate.generation_status !== "success") {
    fail(
      "generation_status只能为success或insufficient",
      rootTask(
        "GENERATION_STATUS",
        ["generation_status"],
        "根据实际结果输出success或insufficient"
      )
    );
  }
  if (candidate.question_count !== 5) {
    fail(
      "success时question_count必须为5",
      rootTask("QUESTION_COUNT", ["question_count", "questions"], "success时完整生成Q1至Q5")
    );
  }
  if (!Array.isArray(candidate.questions) || candidate.questions.length !== 5) {
    fail(
      "success时questions必须恰好包含5题",
      rootTask("QUESTION_SET_SIZE", ["questions"], "FULL重建恰好Q1至Q5五题")
    );
  }
  if (
    !Array.isArray(candidate.missing_information) ||
    candidate.missing_information.length !== 0
  ) {
    fail(
      "success时missing_information必须为空数组",
      rootTask("SUCCESS_MISSING_INFORMATION", ["missing_information"], "success时清空missing_information")
    );
  }
  if (candidate.risk_message !== "") {
    fail(
      "success时risk_message必须为空字符串",
      rootTask("SUCCESS_RISK_MESSAGE", ["risk_message"], "success时risk_message必须为空字符串")
    );
  }

  const evidenceById = new Map();
  const evidenceByLocator = new Map();
  for (const record of records) {
    const evidenceId = record.evidence_id;
    if (nonEmptyString(evidenceId)) {
      const list = evidenceById.get(evidenceId) || [];
      list.push(record);
      evidenceById.set(evidenceId, list);
    }
    if (hasOwn(record, "doc_id") && hasOwn(record, "split_index")) {
      const locator = locatorKey(record.doc_id, record.split_index);
      const list = evidenceByLocator.get(locator) || [];
      list.push(record);
      evidenceByLocator.set(locator, list);
    }
  }

  const hydratedQuestions = [];
  const citedRecords = [];
  const citedEvidenceIds = new Set();
  const locatorUsage = new Map();
  let hardCount = 0;
  let reasoningCount = 0;

  for (let index = 0; index < questions.length; index++) {
    const question = questions[index];
    const expectedId = `Q${index + 1}`;
    const taskId =
      question && typeof question === "object" && /^Q[1-5]$/.test(String(question.id))
        ? String(question.id)
        : expectedId;

    if (!question || typeof question !== "object" || Array.isArray(question)) {
      fail(
        `第${index + 1}题不是对象`,
        setTask("QUESTION_NOT_OBJECT", [expectedId], `完整重建${expectedId}`)
      );
      hydratedQuestions.push(question);
      continue;
    }

    for (const field of INTERNAL_QUESTION_FIELDS) {
      if (!hasOwn(question, field)) {
        fail(
          `${taskId}缺少字段：${field}`,
          questionTask(taskId, "QUESTION_FIELD_MISSING", [field], `补齐${taskId}.${field}`)
        );
      }
    }
    const forbiddenFields = FORBIDDEN_MODEL_METADATA.filter((field) =>
      hasOwn(question, field)
    );
    if (forbiddenFields.length > 0) {
      fail(
        `${taskId}包含禁止由模型填写的来源元数据：${forbiddenFields.join("、")}`,
        questionTask(
          taskId,
          "MODEL_SUPPLIED_EVIDENCE_METADATA",
          forbiddenFields,
          "删除模型填写的来源元数据，只保留evidence_id、support_mode与evidence_summary"
        )
      );
    }
    if (question.id !== expectedId) {
      fail(
        `第${index + 1}题id必须为${expectedId}`,
        setTask("QUESTION_ID_SEQUENCE", questions.map((item, i) => `Q${i + 1}`), "FULL重建并按Q1至Q5编号")
      );
    }
    if (!ABILITY_TYPES.has(question.type)) {
      fail(
        `${taskId}的type不在六项允许值中`,
        questionTask(taskId, "ABILITY_TYPE", ["type"], "将type改为匹配主要能力的允许值")
      );
    }
    for (const field of [
      "phase",
      "timepoint",
      "question",
      "answer_text",
      "explain",
      "keyPoint",
      "evidence_id",
      "support_mode",
      "evidence_summary"
    ]) {
      if (!nonEmptyString(question[field])) {
        fail(
          `${taskId}的${field}必须为非空字符串`,
          questionTask(taskId, "EMPTY_FIELD", [field], `补齐${taskId}.${field}`)
        );
      }
    }

    if (!Array.isArray(question.options) || question.options.length !== 4) {
      fail(
        `${taskId}的options必须恰好4项`,
        questionTask(taskId, "OPTION_COUNT", ["options", "answer", "answer_text"], "重建4个选项并同步答案")
      );
    } else {
      if (question.options.some((option) => !nonEmptyString(option))) {
        fail(
          `${taskId}存在空选项或非字符串选项`,
          questionTask(taskId, "EMPTY_OPTION", ["options", "answer", "answer_text"], "重建4个非空字符串选项并同步答案")
        );
      }
      const normalizedOptions = question.options.map(normalizedText);
      if (new Set(normalizedOptions).size !== 4) {
        fail(
          `${taskId}存在重复选项`,
          questionTask(taskId, "DUPLICATE_OPTIONS", ["options", "answer", "answer_text"], "重建4个互不重复的选项并同步答案")
        );
      }
      if (
        question.options.some((option) =>
          /以上(?:都|全|均)(?:是|正确)|以上(?:都|均)不是/.test(String(option))
        )
      ) {
        fail(
          `${taskId}包含以上都是/以上都不是类选项`,
          questionTask(taskId, "SHORTCUT_OPTION", ["options", "answer", "answer_text"], "用独立且可判断的临床干扰项替换捷径选项")
        );
      }
      question.options.forEach((option, optionIndex) => {
        if (typeof option === "string" && option.length > 60) {
          fail(
            `${taskId}选项${optionIndex + 1}超过60字`,
            questionTask(taskId, "OPTION_LENGTH", ["options", "answer", "answer_text"], "在不改变医学结论的前提下将每个选项限制在60字内")
          );
        }
      });
    }

    if (!Number.isInteger(question.answer) || question.answer < 0 || question.answer > 3) {
      fail(
        `${taskId}的answer必须为0至3整数`,
        questionTask(taskId, "ANSWER_INDEX", ["options", "answer", "answer_text"], "修复答案索引并同步answer_text")
      );
    } else if (
      !Array.isArray(question.options) ||
      question.answer_text !== question.options[question.answer]
    ) {
      fail(
        `${taskId}的answer_text与options[answer]不逐字一致`,
        questionTask(taskId, "ANSWER_TEXT_MISMATCH", ["options", "answer", "answer_text"], "使answer_text逐字等于options[answer]")
      );
    }

    if (forbiddenAnswerLetter(question.explain) || forbiddenAnswerLetter(question.keyPoint)) {
      fail(
        `${taskId}的解析或keyPoint含答案字母引用`,
        questionTask(taskId, "ANSWER_LETTER_REFERENCE", ["explain", "keyPoint"], "删除对A/B/C/D或选项字母的指代")
      );
    }
    for (const [field, limit] of [
      ["question", 160],
      ["explain", 160],
      ["keyPoint", 70],
      ["evidence_summary", 80]
    ]) {
      if (typeof question[field] === "string" && question[field].length > limit) {
        fail(
          `${taskId}的${field}超过${limit}字`,
          questionTask(taskId, `${field.toUpperCase()}_LENGTH`, [field], `在不改变医学结论的前提下将${field}限制在${limit}字内`)
        );
      }
    }

    if (!SUPPORT_MODES.has(question.support_mode)) {
      fail(
        `${taskId}的support_mode只能为hard或clinical_reasoning`,
        questionTask(taskId, "SUPPORT_MODE", ["support_mode", "evidence_id", "evidence_summary"], "根据实际证据重新选择允许的support_mode")
      );
    }

    const matches = nonEmptyString(question.evidence_id)
      ? evidenceById.get(question.evidence_id) || []
      : [];
    let record = null;
    let evidenceType = "";
    if (matches.length !== 1) {
      fail(
        `${taskId}的evidence_id在证据池中匹配${matches.length}条，必须恰好1条`,
        questionTask(taskId, "EVIDENCE_ID_NOT_UNIQUE", ["evidence_id", "support_mode", "evidence_summary"], "改用证据池中可唯一定位且直接支持答案的evidence_id")
      );
    } else {
      record = matches[0];
      const locator = locatorKey(record.doc_id, record.split_index);
      const locatorMatches = evidenceByLocator.get(locator) || [];
      if (locatorMatches.length !== 1) {
        fail(
          `${taskId}绑定记录的doc_id+split_index在证据池中匹配${locatorMatches.length}条`,
          rootTask("EVIDENCE_LOCATOR_NOT_UNIQUE", ["evidence_pool"], "修复证据注册去重后重新装配")
        );
      }
      if (question.support_mode === "clinical_reasoning") {
        evidenceType = "病例+临床推理";
        if (!recordReasoningEligible(record)) {
          fail(
            `${taskId}声明clinical_reasoning，但绑定记录未被证据注册节点确认为可引用来源`,
            questionTask(taskId, "REASONING_EVIDENCE_INELIGIBLE", FULL_INTERNAL_FIELDS, "用合格指南、原始研究或身份可机械确认的高质量二级资料完整重建该题")
          );
        } else {
          reasoningCount += 1;
        }
      } else if (question.support_mode === "hard") {
        evidenceType = recordHardType(record);
        if (!evidenceType) {
          fail(
            `${taskId}声明hard，但绑定记录未被证据注册节点确定为合格指南或临床研究`,
            questionTask(taskId, "HARD_EVIDENCE_INELIGIBLE", FULL_INTERNAL_FIELDS, "用合格硬证据完整重建该题，或在非高风险结论下改为真实的临床推理题")
          );
        } else {
          hardCount += 1;
        }
      }
      if (!nonEmptyString(record.source_title)) {
        fail(
          `${taskId}绑定记录缺少source_title`,
          rootTask("SOURCE_TITLE_MISSING", ["evidence_pool"], "修复证据注册的正式来源名称后重新装配")
        );
      }
      if (!nonEmptyString(record.doc_id)) {
        fail(
          `${taskId}绑定记录缺少doc_id`,
          rootTask("DOC_ID_MISSING", ["evidence_pool"], "修复证据注册定位后重新装配")
        );
      }
      if (!hasOwn(record, "split_index") || record.split_index === "") {
        fail(
          `${taskId}绑定记录缺少split_index`,
          rootTask("SPLIT_INDEX_MISSING", ["evidence_pool"], "修复证据注册定位后重新装配")
        );
      }

      const uses = locatorUsage.get(locator) || [];
      uses.push({
        id: taskId,
        timepoint: question.timepoint,
        answer_text: question.answer_text,
        keyPoint: question.keyPoint
      });
      locatorUsage.set(locator, uses);
      if (!citedEvidenceIds.has(record.evidence_id)) {
        citedEvidenceIds.add(record.evidence_id);
        citedRecords.push(record);
      }
    }

    hydratedQuestions.push(hydrateQuestion(question, record, evidenceType));
  }

  for (const [locator, uses] of locatorUsage.entries()) {
    const targetIds = uses.map((use) => use.id).filter((id) => /^Q[1-5]$/.test(id));
    if (uses.length > 2) {
      fail(
        `证据定位${locator}被使用${uses.length}次，超过最多2题`,
        setTask("EVIDENCE_REUSED_OVER_LIMIT", targetIds, "重建受影响题，使同一证据定位最多支持2题")
      );
    }
    if (uses.length === 2) {
      for (const field of ["timepoint", "answer_text", "keyPoint"]) {
        const first = uses[0][field];
        const second = uses[1][field];
        if (!nonEmptyString(first) || !nonEmptyString(second)) {
          fail(
            `证据定位${locator}二次使用时两题的${field}必须均非空`,
            setTask("EVIDENCE_REUSE_EMPTY_FIELD", targetIds, `重建受影响题并补齐不同的${field}`)
          );
        } else if (normalizedText(first) === normalizedText(second)) {
          fail(
            `证据定位${locator}二次使用时两题的${field}必须不同`,
            setTask("EVIDENCE_REUSE_NOT_DISTINCT", targetIds, `重建受影响题，使两题的${field}实质不同`)
          );
        }
      }
    }
  }

  const allExpectedIds = ["Q1", "Q2", "Q3", "Q4", "Q5"];
  if (hardCount < 2) {
    fail(
      "五题中经证据记录确认的hard题少于2道",
      setTask("HARD_QUOTA", allExpectedIds, "FULL重建题集，使合格hard题不少于2道")
    );
  }
  if (reasoningCount < 2) {
    fail(
      "五题中可定位的clinical_reasoning题少于2道",
      setTask("CLINICAL_REASONING_QUOTA", allExpectedIds, "FULL重建题集，使clinical_reasoning题不少于2道")
    );
  }

  publicCandidate.questions = hydratedQuestions;
  for (const question of hydratedQuestions) {
    if (!question || typeof question !== "object" || Array.isArray(question)) continue;
    const ref = question.guidelineRef;
    if (!ref || typeof ref !== "object" || Array.isArray(ref)) {
      fail(
        `${question.id || "题目"}装配后的guidelineRef无效`,
        rootTask("HYDRATION_FAILED", ["guidelineRef"], "修复装配节点后重新执行")
      );
      continue;
    }
    for (const field of REF_FIELDS) {
      if (!hasOwn(ref, field)) {
        fail(
          `${question.id || "题目"}装配后的guidelineRef缺少${field}`,
          rootTask("HYDRATED_REF_FIELD_MISSING", [field], "修复确定性证据装配")
        );
      }
    }
  }

  return buildReturn({
    decision: errors.length === 0 ? "PASS" : "FAIL",
    medicalAuditable,
    publicCandidate,
    internalRaw: candidateResult.raw,
    citedRecords,
    validatorEvidence: citedRecords,
    hardCount,
    reasoningCount
  });
}

